import * as crypto from 'crypto';

export function hmacSha256(message: string, secret: string): string {
  return crypto.createHmac('sha256', secret).update(message).digest('hex');
}

export function safeEqual(a: string, b: string): boolean {
  const ba = Buffer.from(a);
  const bb = Buffer.from(b);
  return ba.length === bb.length && crypto.timingSafeEqual(ba, bb);
}

type N = { p: number[]; axis: number; l: N | null; r: N | null };
export class KdTree2D {
  private root: N | null;
  constructor(points: number[][]) {
    const build = (pts: number[][], depth: number): N | null => {
      if (!pts.length) return null;
      const axis = depth % 2;
      const sorted = pts.slice().sort((a, b) => a[axis] - b[axis]);
      const mid = sorted.length >> 1;
      return { p: sorted[mid], axis, l: build(sorted.slice(0, mid), depth + 1), r: build(sorted.slice(mid + 1), depth + 1) };
    };
    this.root = build(points, 0);
  }
  nearest(x: number, y: number) {
    let best: N | null = null;
    let bestD = Infinity;
    const distSq = (p: number[]) => (p[0] - x) ** 2 + (p[1] - y) ** 2;
    const walk = (n: N | null): void => {
      if (!n) return;
      const d = distSq(n.p);
      if (d < bestD) { bestD = d; best = n; }
      const diff = (x - n.p[0]) * (n.axis === 0 ? 1 : 0) + (y - n.p[1]) * (n.axis === 1 ? 1 : 0);
      walk(diff < 0 ? n.l : n.r);
      if (diff * diff < bestD) walk(diff < 0 ? n.r : n.l);
    };
    walk(this.root);
    return { point: best!.p, distSq: bestD };
  }
}

export class KeyboardGrid {
  constructor(scope: HTMLElement, cols: number)
  attach(): void
}

export class KeyboardGrid {
  constructor(private scope: HTMLElement, private cols: number) {}
  attach() {
    const cells = [...this.scope.querySelectorAll<HTMLElement>('[role="gridcell"], [role="option"]')];
    if (!cells.length) return;
    cells[0].setAttribute('tabindex', '0');
    const move = (from: number, dc: number, dr: number) => {
      const r = Math.floor(from / this.cols), c = from % this.cols;
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nc < 0 || nc >= this.cols) return;
      const idx = nr * this.cols + nc;
      if (idx >= cells.length) return;
      cells.forEach((el, i) => el.setAttribute('tabindex', i === idx ? '0' : '-1'));
      cells[idx].focus();
    };
    this.scope.addEventListener('keydown', (e) => {
      const idx = cells.indexOf(document.activeElement as HTMLElement);
      if (idx === -1) return;
      const step = e.key === 'ArrowRight' ? () => move(idx, 1, 0) : e.key === 'ArrowLeft' ? () => move(idx, -1, 0)
        : e.key === 'ArrowDown' ? () => move(idx, 0, 1) : e.key === 'ArrowUp' ? () => move(idx, 0, -1)
        : e.key === 'Home' ? () => { cells[0].focus(); } : e.key === 'End' ? () => { cells[cells.length - 1].focus(); } : null;
      if (step) { e.preventDefault(); step(); }
    });
  }
}

export function mergeIntervals(intervals: Interval[]) {
  if (!intervals.length) return [];
  const sorted = intervals.slice().sort((a, b) => a.start - b.start);
  const out: Interval[] = [sorted[0]];
  for (const iv of sorted.slice(1)) {
    const last = out[out.length - 1];
    if (iv.start <= last.end) last.end = Math.max(last.end, iv.end);
    else out.push({ ...iv });
  }
  return out;
}

