export class Noise2D {
  private perm: number[] = [];
  constructor(seed = 1337) {
    let s = seed;
    const rand = () => { s |= 0; s = (s + 0x6d2b79f5) | 0; let t = Math.imul(s ^ (s >>> 15), 1 | s); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
    this.perm = Array.from({ length: 512 }, (_, i) => (i % 256));
    for (let i = 255; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [this.perm[i], this.perm[j]] = [this.perm[j], this.perm[i]]; }
    for (let i = 0; i < 256; i++) this.perm[256 + i] = this.perm[i];
  }
  private hash(x: number, y: number) { return this.perm[(this.perm[x & 255] + y) & 255]; }
  private smooth(t: number) { return t * t * (3 - 2 * t); }
  value(x: number, y: number) {
    const xi = Math.floor(x), yi = Math.floor(y);
    const xf = x - xi, yf = y - yi;
    const u = this.smooth(xf), v = this.smooth(yf);
    const a = this.hash(xi, yi), b = this.hash(xi + 1, yi), c = this.hash(xi, yi + 1), d = this.hash(xi + 1, yi + 1);
    return (a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v) / 255;
  }
  fbm(x: number, y: number, octaves = 4) {
    let sum = 0, amp = 1, freq = 1, norm = 0;
    for (let i = 0; i < octaves; i++) { sum += this.value(x * freq, y * freq) * amp; norm += amp; amp *= 0.5; freq *= 2; }
    return sum / norm;
  }
}

export function registerShortcuts(defs: ShortcutDef[]) {
  const handler = (e: KeyboardEvent) => {
    for (const d of defs) {
      if (d.ignoreInInputs && /^(input|textarea|select)$/i.test((e.target as HTMLElement)?.tagName ?? '')) continue;
      const parts = d.combo.toLowerCase().split('+');
      const key = parts[parts.length - 1];
      const mods = parts.slice(0, -1);
      if (e.key.toLowerCase() !== key) continue;
      if (mods.includes('ctrl') !== e.ctrlKey) continue;
      if (mods.includes('shift') !== e.shiftKey) continue;
      if (mods.includes('alt') !== e.altKey) continue;
      if (mods.includes('meta') !== e.metaKey) continue;
      e.preventDefault();
      d.handler(e);
      return;
    }
  };
  window.addEventListener('keydown', handler);
  return () => window.removeEventListener('keydown', handler);
}

export function watchAppState(onChange: (state: 'background' | 'foreground') => void) {
  let hidden = document.visibilityState === 'hidden';
  const vis = () => { const h = document.visibilityState === 'hidden'; if (h !== hidden) { hidden = h; onChange(h ? 'background' : 'foreground'); } };
  document.addEventListener('visibilitychange', vis);
  window.addEventListener('pageshow', () => { if (hidden) { hidden = false; onChange('foreground'); } });
  return () => { document.removeEventListener('visibilitychange', vis); window.removeEventListener('pageshow', () => {}); };
}

