export function diffSummary(unifiedDiff: string) {
  const stats: DiffStat[] = [];
  let cur: DiffStat | null = null;
  for (const line of unifiedDiff.split('\n')) {
    if (line.startsWith('+++ ')) {
      const file = line.slice(4).trim();
      cur = { file, added: 0, removed: 0 };
      stats.push(cur);
    } else if (cur) {
      if (line.startsWith('+')) cur.added++;
      else if (line.startsWith('-')) cur.removed++;
    }
  }
  return stats;
}

export function wordWrap(text: string, width: number) {
  const lines: string[] = [];
  for (const para of text.split('\n')) {
    let line = '';
    for (const word of para.split(/\s+/)) {
      if (!word) continue;
      if (line && line.length + 1 + word.length > width) { lines.push(line); line = word; }
      else if (line) line += ' ' + word;
      else line = word;
      while (line.length > width) { lines.push(line.slice(0, width)); line = line.slice(width); }
    }
    if (line) lines.push(line);
  }
  return lines;
}

export type Cell = 'X' | 'O' | null;
export function checkTicTacToe(board: Cell[]): { winner: 'X' | 'O'; line: number[] } | { winner: null; draw: boolean }

const LINES = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8],
  [0, 3, 6], [1, 4, 7], [2, 5, 8],
  [0, 4, 8], [2, 4, 6],
];

export function checkTicTacToe(board: Cell[]) {
  for (const line of LINES) {
    const [a, b, c] = line;
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return { winner: board[a] as 'X' | 'O', line };
    }
  }
  return { winner: null, draw: board.every((c) => c !== null) };
}

export function expandRoles(role: string, parents: Record<string, string[]>): string[]

export function expandRoles(role: string, parents: Record<string, string[]>) {
  const seen = new Set<string>();
  const visit = (r: string) => {
    if (seen.has(r)) return;
    seen.add(r);
    for (const p of parents[r] ?? []) visit(p);
  };
  visit(role);
  return [...seen];
}

