export class AppError extends Error {
  constructor(message: string, public status = 400, public details?: unknown) {
    super(message);
    this.name = 'AppError';
  }
}

export function withErrorHandling(handler: (req: HttpRequest) => Promise<HttpResponse>) {
  return async (req: HttpRequest): Promise<HttpResponse> => {
    try {
      return await handler(req);
    } catch (e) {
      if (e instanceof AppError) {
        return { status: e.status, body: { ok: false, error: e.message, ...(e.details !== undefined ? { details: e.details } : {}) } };
      }
      console.error('[api] unhandled', e);
      return { status: 500, body: { ok: false, error: 'internal_error' } };
    }
  };
}

export function heatmapColor(v: number, min: number, max: number): string

export function heatmapColor(v: number, min: number, max: number) {
  const t = max === min ? 0.5 : (v - min) / (max - min);
  const r = Math.round(255 * Math.min(1, Math.max(0, (t - 0.5) * 2)));
  const b = Math.round(255 * Math.min(1, Math.max(0, (0.5 - t) * 2)));
  const g = Math.round(255 * (1 - Math.abs(t - 0.5) * 2));
  return `rgb(${r},${g},${b})`;
}

export function trimPrompt(system: string, context: string[], query: string, maxTokens: number) {
  const len = (s: string) => Math.ceil(s.length / 4);
  let budget = maxTokens - len(system) - len(query);
  const kept: string[] = [];
  for (const c of context) { if (len(c) > budget) break; kept.push(c); budget -= len(c); }
  return { system, context: kept, query };
}

export interface SessionState<T> { version: number; data: T; savedAt: number }
export class SessionStore<T> {
  constructor(key: string, version: number, store?: { load: () => string | null; save: (s: string) => void })
  restore(): T | null
  save(data: T): void
  clear(): void
}

export class SessionStore<T> {
  constructor(private key: string, private version: number, private store: { load: () => string | null; save: (s: string) => void } = {
    load: () => localStorage.getItem(key),
    save: (s) => localStorage.setItem(key, s),
  }) {}
  restore(): T | null {
    try {
      const raw = this.store.load();
      if (!raw) return null;
      const parsed = JSON.parse(raw) as SessionState<T>;
      return parsed.version === this.version ? parsed.data : null;
    } catch { return null; }
  }
  save(data: T) { this.store.save(JSON.stringify({ version: this.version, data, savedAt: Date.now() })); }
  clear() { this.store.save(''); }
}

export function createWsClient(url: string, options?: { protocols?: string[] }) {
  let ws: WebSocket | null = null;
  const listeners = new Set<(data: unknown) => void>();

  return {
    async connect() {
      ws = new WebSocket(url, options?.protocols);
      ws.onmessage = (ev) => {
        let parsed: unknown = ev.data;
        if (typeof ev.data === 'string') { try { parsed = JSON.parse(ev.data); } catch { /* keep raw */ } }
        listeners.forEach((cb) => cb(parsed));
      };
      await new Promise<void>((resolve, reject) => {
        if (!ws) return reject(new Error('no_ws'));
        ws.onopen = () => resolve();
        ws.onerror = () => reject(new Error('ws_error'));
      });
    },
    send(data) {
      ws?.send(typeof data === 'string' ? data : JSON.stringify(data));
    },
    onMessage(cb) { listeners.add(cb); return () => listeners.delete(cb); },
    close() {
      return new Promise<void>((resolve) => {
        if (!ws) return resolve();
        ws.onclose = () => resolve();
        ws.close();
      });
    },
    get state() { return ws?.readyState === 1 ? 'open' : (ws?.readyState === 0 ? 'connecting' : 'closed'); },
  };
}

