};
export function statusText(code: number) { return REASONS[code] ?? 'Unknown'; }
export function statusClass(code: number) {
  const c = Math.floor(code / 100);
  return (c >= 1 && c <= 5 ? c + 'xx' : 'other') as '1xx' | '2xx' | '3xx' | '4xx' | '5xx' | 'other';
}

export function parseEnv(content: string) {
  const out: Record<string, string> = {};
  for (const line of content.split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const eq = t.indexOf('=');
    if (eq < 0) continue;
    const key = t.slice(0, eq).trim();
    let val = t.slice(eq + 1).trim();
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }
    out[key] = val;
  }
  return out;
}
export function serializeEnv(env: Record<string, string>) {
  return Object.entries(env).map(([k, v]) => `${k}=${/[\s#]/.test(v) ? JSON.stringify(v) : v}`).join('\n') + '\n';
}

export class Presence {
  constructor(ttlMs?: number)
  touch(userId: string, meta?: Record<string, unknown>): void
  sweep(): string[]
  get online(): Array<{ userId: string; meta?: Record<string, unknown> }>
}

export class Presence {
  private users = new Map<string, { last: number; meta?: Record<string, unknown> }>();
  constructor(private ttlMs = 30000) {}
  touch(userId: string, meta?: Record<string, unknown>) { this.users.set(userId, { last: Date.now(), meta }); }
  sweep() {
    const now = Date.now();
    const gone: string[] = [];
    for (const [id, u] of this.users) if (now - u.last > this.ttlMs) { this.users.delete(id); gone.push(id); }
    return gone;
  }
  get online() {
    this.sweep();
    return [...this.users.entries()].map(([userId, u]) => ({ userId, meta: u.meta }));
  }
}

