export function allocate(total: number, weights: Record<string, number>) {
  const out: Record<string, number> = {};
  for (const [name, w] of Object.entries(weights)) out[name] = total * w;
  return out;
}

export class Container {
  private factories = new Map<string, () => unknown>();
  private singletons = new Map<string, unknown>();
  register<T>(name: string, factory: () => T) { this.factories.set(name, factory); }
  resolve<T>(name: string): T {
    const f = this.factories.get(name);
    if (!f) throw new Error(`Unregistered dependency: ${name}`);
    return f() as T;
  }
  singleton<T>(name: string): T {
    if (!this.singletons.has(name)) this.singletons.set(name, this.resolve<T>(name));
    return this.singletons.get(name) as T;
  }
}

export class LogisticRegression {
  constructor(dim: number)
  fit(samples: { x: number[]; label: number }[], epochs = 50, lr = 0.01): void
  predict(x: number[]): number
}

export class LogisticRegression {
  private w: number[]; private b = 0;
  constructor(dim: number) { this.w = new Array(dim).fill(0); }
  private sigmoid(z: number) { return 1 / (1 + Math.exp(-z)); }
  fit(samples: { x: number[]; label: number }[], epochs = 50, lr = 0.01) {
    for (let e = 0; e < epochs; e++) {
      for (const s of samples) {
        const p = this.sigmoid(this.w.reduce((sum, wi, i) => sum + wi * s.x[i], 0) + this.b);
        const err = p - (s.label > 0 ? 1 : 0);
        for (let i = 0; i < this.w.length; i++) this.w[i] -= lr * err * s.x[i];
        this.b -= lr * err;
      }
    }
  }
  predict(x: number[]) {
    return this.sigmoid(this.w.reduce((s, wi, i) => s + wi * x[i], 0) + this.b);
  }
}

export function interpolationSearch(sorted: number[], target: number) {
  let lo = 0, hi = sorted.length - 1;
  while (lo <= hi && target >= sorted[lo] && target <= sorted[hi]) {
    const span = sorted[hi] - sorted[lo];
    const pos = span === 0 ? lo : lo + Math.floor(((target - sorted[lo]) * (hi - lo)) / span);
    if (sorted[pos] === target) return pos;
    if (sorted[pos] < target) lo = pos + 1; else hi = pos - 1;
  }
  return -1;
}

