}

export class ClockOffset {
  private offsets: number[] = [];
  private rtts: number[] = [];
  constructor(private maxSamples = 20) {}
  observe(sent: number, serverTime: number, received: number) {
    const rtt = received - sent;
    this.offsets.push(serverTime - (sent + received) / 2);
    this.rtts.push(rtt);
    if (this.offsets.length > this.maxSamples) { this.offsets.shift(); this.rtts.shift(); }
  }
  private median(arr: number[]) { const s = [...arr].sort((a, b) => a - b); const n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; }
  get offsetMs() { return this.offsets.length ? this.median(this.offsets) : 0; }
  get rttMs() { return this.rtts.length ? this.median(this.rtts) : 0; }
  estimateServerNow() { return Date.now() + this.offsetMs; }
}

export type Handler<T> = (req: T, next: () => T) => T
export function chain<T>(handlers: Handler<T>[]): (req: T) => T

export function chain<T>(handlers: Handler<T>[]) {
  return (req: T) => {
    let i = 0;
    const next = (): T => {
      const h = handlers[i++];
      if (!h) return req;
      return h(req, next);
    };
    return next();
  };
}

export class Mulberry32 {
  private s: number;
  constructor(seed = Date.now() >>> 0) { this.s = seed >>> 0; }
  next() { this.s = (this.s + 0x6d2b79f5) >>> 0; let t = this.s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
  int(min: number, max: number) { return min + Math.floor(this.next() * (max - min + 1)); }
  shuffle<T>(arr: T[]) { const a = arr.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(this.next() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
}

