export type TextOp = { type: 'insert'; pos: number; text: string } | { type: 'delete'; pos: number; len: number }
export function applyOp(text: string, op: TextOp): string
export function transform(a: TextOp, against: TextOp): TextOp
export function compose(a: TextOp, b: TextOp): TextOp

export function applyOp(text: string, op: TextOp) {
  if (op.type === 'insert') return text.slice(0, op.pos) + op.text + text.slice(op.pos);
  return text.slice(0, op.pos) + text.slice(op.pos + op.len);
}
export function transform(a: TextOp, against: TextOp): TextOp {
  if (against.type === 'insert') {
    if (a.pos >= against.pos) return { ...a, pos: a.pos + against.text.length };
    return a;
  }
  // against is delete
  if (a.type === 'insert') {
    if (a.pos > against.pos) return { ...a, pos: a.pos - Math.min(against.len, a.pos - against.pos) };
    return a;
  }
  // both delete
  if (a.pos >= against.pos + against.len) return { ...a, pos: a.pos - against.len };
  if (a.pos >= against.pos) return { ...a, pos: against.pos, len: Math.max(0, a.len - (against.pos + against.len - a.pos)) };
  return a;
}
export function compose(a: TextOp, b: TextOp): TextOp {
  const t = transform(b, a);
  if (a.type === 'insert' && t.type === 'insert') return { type: 'insert', pos: a.pos, text: a.text + t.text };
  return t;
}

export function colorLerp(a: string, b: string, t: number): string

function parseHex(h: string) {
  const s = h.replace('#', '');
  const f = s.length === 3 ? s.split('').map((c) => c + c).join('') : s;
  return [0, 2, 4].map((i) => parseInt(f.slice(i, i + 2), 16));
}
export function colorLerp(a: string, b: string, t: number) {
  const ca = parseHex(a), cb = parseHex(b);
  const k = Math.max(0, Math.min(1, t));
  const mix = ca.map((v, i) => Math.round(v + (cb[i] - v) * k));
  return `#${mix.map((c) => c.toString(16).padStart(2, '0')).join('')}`;
}

function bm25(query: string, text: string) {
  const q = new Set(query.toLowerCase().match(/[a-z0-9]+/g) ?? []);
  const t = text.toLowerCase().match(/[a-z0-9]+/g) ?? [];
  const tf = new Map<string, number>();
  for (const w of t) tf.set(w, (tf.get(w) ?? 0) + 1);
  let score = 0;
  for (const w of q) score += Math.log(1 + (tf.get(w) ?? 0));
  return score;
}
export function hybridRetrieve(query: string, queryVec: number[], docs: HybridDoc[], k = 3) {
  let maxB = 0, maxC = 0;
  const scored = docs.map((d) => {
    let dot = 0, na = 0, nb = 0;
    for (let i = 0; i < queryVec.length; i++) { dot += queryVec[i] * d.vector[i]; na += queryVec[i] ** 2; nb += d.vector[i] ** 2; }
    const cosine = dot / (Math.sqrt(na) * Math.sqrt(nb) || 1);
    const lexical = bm25(query, d.text);
    maxB = Math.max(maxB, lexical); maxC = Math.max(maxC, cosine);
    return { id: d.id, lexical, cosine };
  });
  return scored
    .map((s) => ({ id: s.id, score: (s.cosine / (maxC || 1)) + (s.lexical / (maxB || 1)) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, k);
}

