export interface CsrfRecord { token: string; expiresAt: number }
export function validateCsrf(record: CsrfRecord | null, presented: string, now?: number): boolean

export function validateCsrf(record: CsrfRecord | null, presented: string, now = Date.now()) {
  if (!record || record.expiresAt < now || !presented) return false;
  if (record.token.length !== presented.length) return false;
  let diff = 0;
  for (let i = 0; i < record.token.length; i++) diff |= record.token.charCodeAt(i) ^ presented.charCodeAt(i);
  return diff === 0;
}

export type Connect4Cell = 1 | 2 | null;
export function dropDisc(board: Connect4Cell[][], column: number, player: 1 | 2): { ok: boolean; row?: number }
export function checkConnect4Win(board: Connect4Cell[][], row: number, col: number): boolean

export function dropDisc(board: Connect4Cell[][], column: number, player: 1 | 2): { ok: boolean; row?: number } {
  for (let r = board.length - 1; r >= 0; r--) {
    if (board[r][column] === null) {
      board[r][column] = player;
      return { ok: true, row: r };
    }
  }
  return { ok: false };
}

export function checkConnect4Win(board: Connect4Cell[][], row: number, col: number): boolean {
  const player = board[row][col];
  if (player === null) return false;
  const dirs = [[0, 1], [1, 0], [1, 1], [1, -1]];
  for (const [dr, dc] of dirs) {
    let count = 1;
    for (const sign of [1, -1]) {
      let r = row + dr * sign, c = col + dc * sign;
      while (r >= 0 && r < board.length && c >= 0 && c < board[0].length && board[r][c] === player) {
        count++;
        r += dr * sign; c += dc * sign;
      }
    }
    if (count >= 4) return true;
  }
  return false;
}

