  constructor(fps = 12) { this._fps = fps; }
  update(dt: number) {
    this.acc += dt;
    const frameMs = 1 / this._fps;
    while (this.acc >= frameMs) { this.acc -= frameMs; this._frame++; }
  }
  reset() { this.acc = 0; this._frame = 0; }
  get frame() { return this._frame; }
  set fps(fps: number) { this._fps = Math.max(1, fps); }
}

export class KeyboardGrid {
  constructor(private scope: HTMLElement, private cols: number) {}
  attach() {
    const cells = [...this.scope.querySelectorAll<HTMLElement>('[role="gridcell"], [role="option"]')];
    if (!cells.length) return;
    cells[0].setAttribute('tabindex', '0');
    const move = (from: number, dc: number, dr: number) => {
      const r = Math.floor(from / this.cols), c = from % this.cols;
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nc < 0 || nc >= this.cols) return;
      const idx = nr * this.cols + nc;
      if (idx >= cells.length) return;
      cells.forEach((el, i) => el.setAttribute('tabindex', i === idx ? '0' : '-1'));
      cells[idx].focus();
    };
    this.scope.addEventListener('keydown', (e) => {
      const idx = cells.indexOf(document.activeElement as HTMLElement);
      if (idx === -1) return;
      const step = e.key === 'ArrowRight' ? () => move(idx, 1, 0) : e.key === 'ArrowLeft' ? () => move(idx, -1, 0)
        : e.key === 'ArrowDown' ? () => move(idx, 0, 1) : e.key === 'ArrowUp' ? () => move(idx, 0, -1)
        : e.key === 'Home' ? () => { cells[0].focus(); } : e.key === 'End' ? () => { cells[cells.length - 1].focus(); } : null;
      if (step) { e.preventDefault(); step(); }
    });
  }
}

export function gridLayout(opts: { width: number; height: number; cols: number; gap?: number; margin?: number }): Array<{ x: number; y: number; w: number; h: number }>

export function gridLayout(opts: { width: number; height: number; cols: number; gap?: number; margin?: number }) {
  const gap = opts.gap ?? 4, margin = opts.margin ?? 0;
  const innerW = opts.width - margin * 2, innerH = opts.height - margin * 2;
  const rows = Math.max(1, Math.ceil((innerH + gap) / (innerW / opts.cols + gap)));
  const cellW = (innerW - gap * (opts.cols - 1)) / opts.cols;
  const cellH = (innerH - gap * (rows - 1)) / rows;
  const out = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < opts.cols; c++) {
    out.push({ x: margin + c * (cellW + gap), y: margin + r * (cellH + gap), w: cellW, h: cellH });
  }
  return out;
}

export function floydWarshall(adj: number[][]) {
  const n = adj.length;
  const dist = adj.map((row) => row.slice());
  for (let k = 0; k < n; k++)
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
  return dist;
}

