export function renderTree(paths: string[]): string

export function renderTree(paths: string[]) {
  const root: Record<string, unknown> = {};
  for (const p of paths) {
    let node = root;
    for (const part of p.split('/')) {
      if (part === '') continue;
      if (typeof node[part] !== 'object' || node[part] === null) node[part] = {};
      node = node[part] as Record<string, unknown>;
    }
  }
  const lines: string[] = [];
  const walk = (node: Record<string, unknown>, prefix: string, isRoot: boolean) => {
    const keys = Object.keys(node).sort();
    keys.forEach((k, i) => {
      const last = i === keys.length - 1;
      lines.push(prefix + (last ? '`- ' : '|- ') + k);
      walk(node[k] as Record<string, unknown>, prefix + (last ? '   ' : '|  '), false);
    });
  };
  walk(root, '', true);
  return lines.join('\n');
}

export async function resizeImage(source: HTMLImageElement | Blob, options: ResizeOptions = {}): Promise<string> {
  const img = source instanceof Blob
    ? await createImageBitmap(source)
    : source;

  const srcW = 'width' in img ? img.width : 0;
  const srcH = 'height' in img ? img.height : 0;
  const maxW = options.maxWidth ?? srcW;
  const maxH = options.maxHeight ?? srcH;

  let scale = Math.min(maxW / srcW, maxH / srcH);
  if (options.mode === 'cover') scale = Math.max(maxW / srcW, maxH / srcH);
  scale = Math.min(1, scale);   // only downscale by default

  const w = Math.max(1, Math.round(srcW * scale));
  const h = Math.max(1, Math.round(srcH * scale));

  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d')!;
  ctx.drawImage(img as CanvasImageSource, 0, 0, w, h);

  const format = options.format ?? 'image/jpeg';
  return canvas.toDataURL(format, options.quality ?? 0.85);
}

export class KdTree2D {
  constructor(points: number[][])
  nearest(x: number, y: number): { point: number[]; distSq: number }
}

type N = { p: number[]; axis: number; l: N | null; r: N | null };
export class KdTree2D {
  private root: N | null;
  constructor(points: number[][]) {
    const build = (pts: number[][], depth: number): N | null => {
      if (!pts.length) return null;
      const axis = depth % 2;
      const sorted = pts.slice().sort((a, b) => a[axis] - b[axis]);
      const mid = sorted.length >> 1;
      return { p: sorted[mid], axis, l: build(sorted.slice(0, mid), depth + 1), r: build(sorted.slice(mid + 1), depth + 1) };
    };
    this.root = build(points, 0);
  }
  nearest(x: number, y: number) {
    let best: N | null = null;
    let bestD = Infinity;
    const distSq = (p: number[]) => (p[0] - x) ** 2 + (p[1] - y) ** 2;
    const walk = (n: N | null): void => {
      if (!n) return;
      const d = distSq(n.p);
      if (d < bestD) { bestD = d; best = n; }
      const diff = (x - n.p[0]) * (n.axis === 0 ? 1 : 0) + (y - n.p[1]) * (n.axis === 1 ? 1 : 0);
      walk(diff < 0 ? n.l : n.r);
      if (diff * diff < bestD) walk(diff < 0 ? n.r : n.l);
    };
    walk(this.root);
    return { point: best!.p, distSq: bestD };
  }
}

export function createLruCache<K, V>(capacity: number) {
  const map = new Map<K, V>();

  return {
    get(key) {
      if (!map.has(key)) return undefined;
      const value = map.get(key)!;
      map.delete(key);          // refresh recency
      map.set(key, value);
      return value;
    },
    set(key, value) {
      if (map.has(key)) map.delete(key);
      map.set(key, value);
      if (map.size > capacity) {
        const oldest = map.keys().next().value;
        if (oldest !== undefined) map.delete(oldest);
      }
    },
    has: (key) => map.has(key),
    delete: (key) => map.delete(key),
    get size() { return map.size; },
    clear: () => map.clear(),
  };
}

export function parseIsoDuration(duration: string) {
  const m = /^P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+(?:\.\d+)?)S)?)?$/.exec(duration);
  if (!m) throw new Error(`Invalid ISO 8601 duration: ${duration}`);
  const [y, mo, d, h, mi, s] = m.slice(1).map((x) => Number(x ?? 0));
  return (((((y * 365 + mo * 30 + d) * 24 + h) * 60 + mi) * 60 + s) * 1000);
}

export async function waitForHealthy(check: () => Promise<boolean>, opts = {}) {
  const { intervalMs = 1000, timeoutMs = 60000 } = opts;
