import * as net from 'net';

async function checkPort(host: string, port: number, timeoutMs: number): Promise<boolean> {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    socket.setTimeout(timeoutMs);
    socket.once('connect', () => { socket.destroy(); resolve(true); });
    socket.once('timeout', () => { socket.destroy(); resolve(false); });
    socket.once('error', () => resolve(false));
    socket.connect(port, host);
  });
}

export async function scanPorts(host: string, ports: number[], options?: { concurrency?: number; timeoutMs?: number }): Promise<number[]> {
  const concurrency = options?.concurrency ?? 32;
  const timeoutMs = options?.timeoutMs ?? 1000;
  const open: number[] = [];
  let cursor = 0;

  async function worker() {
    while (cursor < ports.length) {
      const port = ports[cursor++];
      if (await checkPort(host, port, timeoutMs)) open.push(port);
    }
  }

  await Promise.all(Array.from({ length: concurrency }, () => worker()));
  return open.sort((a, b) => a - b);
}

export function alphaBeta<S, M>(
  game: MinimaxGame<S, M>, state: S, depth: number, alpha: number, beta: number, isMax: boolean,
): number {
  if (depth === 0 || game.isTerminal(state)) return game.evaluate(state);
  const moves = game.getMoves(state);
  if (moves.length === 0) return game.evaluate(state);

  if (isMax) {
    let value = -Infinity;
    for (const m of moves) {
      value = Math.max(value, alphaBeta(game, game.apply(state, m), depth - 1, alpha, beta, false));
      alpha = Math.max(alpha, value);
      if (alpha >= beta) break;   // prune
    }
    return value;
  }
  let value = Infinity;
  for (const m of moves) {
    value = Math.min(value, alphaBeta(game, game.apply(state, m), depth - 1, alpha, beta, true));
    beta = Math.min(beta, value);
    if (alpha >= beta) break;     // prune
  }
  return value;
}

export function bestMoveAB<S, M>(game: MinimaxGame<S, M>, state: S, depth = 6): M | null {
  let best: M | null = null;
  let bestScore = -Infinity;
  let alpha = -Infinity;
  const beta = Infinity;
  for (const m of game.getMoves(state)) {
    const score = alphaBeta(game, game.apply(state, m), depth - 1, alpha, beta, false);
    if (score > bestScore) { bestScore = score; best = m; }
    alpha = Math.max(alpha, score);
  }
  return best;
}

export async function withRetry<T>(task: () => Promise<T>, options?: RetryOptions): Promise<T> {
  const attempts = options?.attempts ?? 3;
  const baseMs = options?.baseMs ?? 200;
  const maxMs = options?.maxMs ?? 4000;

  for (let i = 0; i < attempts; i++) {
    try {
      return await task();
    } catch (e) {
      if (i === attempts - 1) throw e;
      if (options?.shouldRetry && !options.shouldRetry(e)) throw e;
      const jitter = Math.random() * baseMs;
      const delay = Math.min(maxMs, baseMs * 2 ** i + jitter);
      await new Promise((r) => setTimeout(r, delay));
    }
  }
  throw new Error('unreachable');
}

export function parseQuery(search: string): Record<string, string>
