  }
}

export function createSlideshow(options?: { intervalMs?: number; loop?: boolean }) {
  const intervalMs = options?.intervalMs ?? 5000;
  const loop = options?.loop ?? true;
  let index = 0;
  let count = 0;
  let timer: ReturnType<typeof setInterval> | undefined;
  const listeners = new Set<(i: number) => void>();

  function notify() { listeners.forEach((cb) => cb(index)); }

  function schedule() {
    if (timer) clearInterval(timer);
    if (count > 1) timer = setInterval(() => next(), intervalMs);
  }

  function next() {
    index = index + 1 >= count ? (loop ? 0 : count - 1) : index + 1;
    notify();
  }

  return {
    get index() { return index; },
    next,
    prev() {
      index = index - 1 < 0 ? (loop ? count - 1 : 0) : index - 1;
      notify();
    },
    goTo(i) {
      if (i < 0 || i >= count) return;
      index = i;
      notify();
    },
    start() { schedule(); },
    stop() { if (timer) clearInterval(timer); timer = undefined; },
    onIndexChange(cb) { listeners.add(cb); return () => listeners.delete(cb); },
    get count() { return count; },
    _setCount(n: number) { count = n; if (index >= count) index = Math.max(0, count - 1); },
  };
}

export function evaluateExpression(expr: string): number {
  const tokens = expr.replace(/\s+/g, '').match(/(\d+\.?\d*|[+\-*/()])/g);
  if (!tokens) throw new Error('invalid_expression');

  const output: string[] = [];
  const ops: string[] = [];
  const precedence: Record<string, number> = { '+': 1, '-': 1, '*': 2, '/': 2 };

  for (const t of tokens) {
    if (/\d/.test(t)) {
      output.push(t);
    } else if (t === '(') {
      ops.push(t);
    } else if (t === ')') {
      while (ops.length && ops[ops.length - 1] !== '(') output.push(ops.pop()!);
      ops.pop();
    } else {
      while (ops.length && precedence[ops[ops.length - 1]] >= precedence[t]) output.push(ops.pop()!);
      ops.push(t);
    }
  }
  while (ops.length) output.push(ops.pop()!);

  const stack: number[] = [];
  for (const t of output) {
    if (/\d/.test(t)) stack.push(Number(t));
    else {
      const b = stack.pop()!, a = stack.pop()!;
      if (t === '+') stack.push(a + b);
      if (t === '-') stack.push(a - b);
      if (t === '*') stack.push(a * b);
      if (t === '/') stack.push(a / b);
    }
  }
  return stack[0];
}

