export function extendedEuclid(a: number, b: number) {
  if (b === 0) return { gcd: a, x: 1, y: 0 };
  const { gcd, x, y } = extendedEuclid(b, a % b);
  return { gcd, x: y, y: x - Math.floor(a / b) * y };
