  async attempt<T>(id: string, fn: () => Promise<T>): Promise<T | 'quarantined'> {
    const n = (this.attempts.get(id) ?? 0) + 1;
    this.attempts.set(id, n);
    try { return await fn(); }
    catch (err) {
      if (n >= this.maxAttempts) { this.attempts.delete(id); return 'quarantined'; }
