}

export function createRateLimiter(options: { windowMs: number; max: number }) {
  const hits = new Map<string, number[]>();

  return {
    check(key: string, now = Date.now()): RateLimitResult {
      const windowStart = now - options.windowMs;
      const list = (hits.get(key) ?? []).filter((t) => t > windowStart);
      list.push(now);
      hits.set(key, list);
      const allowed = list.length <= options.max;
      return {
        allowed,
        remaining: Math.max(0, options.max - list.length),
        retryAfterMs: allowed ? undefined : options.windowMs - (list[0] ?? now),
      };
    },
    clear(key) {
      if (key) hits.delete(key);
      else hits.clear();
    },
  };
}

export function errorBudget(opts: { sloPct: number; windowSeconds: number; unavailableSeconds: number }) {
  const allowed = (1 - opts.sloPct / 100) * opts.windowSeconds;
  const burnedPct = (opts.unavailableSeconds / allowed) * 100;
  return {
    errorBudgetPct: opts.sloPct,
    remaining: Math.max(0, allowed - opts.unavailableSeconds),
    burnedPct: Math.min(100, burnedPct),
  };
}

