export async function runSaga<T>(steps: Array<SagaStep<T>>) {
  const done: Array<SagaStep<T>> = [];
  try {
    for (const s of steps) { await s.run(); done.push(s); }
    return done;
  } catch (err) {
    for (const s of done.reverse()) { try { await s.compensate(); } catch { /* best-effort */ } }
    throw err;
  }
}

export function kmpSearch(text: string, pattern: string) {
  const lps = new Array(pattern.length).fill(0);
  for (let i = 1, len = 0; i < pattern.length; ) {
    if (pattern[i] === pattern[len]) lps[i++] = ++len;
    else if (len) len = lps[len - 1];
    else lps[i++] = 0;
  }
  const hits: number[] = [];
  for (let i = 0, j = 0; i < text.length; i++) {
    while (j > 0 && text[i] !== pattern[j]) j = lps[j - 1];
    if (text[i] === pattern[j]) j++;
    if (j === pattern.length) { hits.push(i - j + 1); j = lps[j - 1]; }
  }
  return hits;
}

const FENCE = '`'.repeat(3);
export function extractJson<T = unknown>(raw: string): T | null {
  const fenced = raw.match(new RegExp(`${FENCE}(?:json)?\\s*([\\s\\S]*?)${FENCE}`));
  const candidate = fenced ? fenced[1] : raw;
  const start = candidate.indexOf('{');
  if (start < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < candidate.length; i++) {
    const ch = candidate[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\' && inStr) { esc = true; continue; }
    if (ch === '"') inStr = !inStr;
    if (inStr) continue;
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) {
      try { return JSON.parse(candidate.slice(start, i + 1)) as T; } catch { return null; }
    } }
  }
  return null;
}

export function createScoreSystem(options?: { comboWindowMs?: number }) {
  const comboWindow = options?.comboWindowMs ?? 2000;
  let score = 0;
  let combo = 0;
  let level = 1;
  let highScore = 0;
  let lastHit = 0;

  return {
    add(points, now = Date.now()) {
      combo = now - lastHit <= comboWindow ? combo + 1 : 1;
      lastHit = now;
      const gained = Math.round(points * (1 + (combo - 1) * 0.1));
      score += gained;
      highScore = Math.max(highScore, score);
      return gained;
    },
    get score() { return score; },
    get combo() { return combo; },
    get level() { return level; },
    setLevel(n) { level = n; },
    get highScore() { return highScore; },
    reset() { score = 0; combo = 0; level = 1; lastHit = 0; },
  };
}

export function resolveRange(header: string | undefined, size: number) {
  if (!header || !header.startsWith('bytes=')) return { status: 200, start: 0, end: size - 1 };
  const spec = header.slice(6).trim();
  const m = /^(\d*)-(\d*)$/.exec(spec);
  if (!m || size === 0) return { status: 416, start: 0, end: -1 };
  let start = m[1] === '' ? 0 : parseInt(m[1], 10);
  let end = m[2] === '' ? size - 1 : parseInt(m[2], 10);
  if (m[1] === '' && m[2] !== '') { start = Math.max(0, size - parseInt(m[2], 10)); end = size - 1; }
  if (start >= size || start > end) return { status: 416, start: 0, end: -1 };
  end = Math.min(end, size - 1);
  return { status: 206, start, end };
}

export interface SpriteSheetConfig { cols: number; rows: number; frameW: number; frameH: number; fps?: number; loop?: boolean }
export function createSpriteAnimator(config: SpriteSheetConfig) {
