export class BatchCollector<T> {
  private items: T[] = [];
  private timer: ReturnType<typeof setTimeout> | null = null;
  constructor(private opts: { maxSize: number; flushMs: number; onFlush: (items: T[]) => void }) {}
  push(item: T) {
    this.items.push(item);
    if (this.items.length >= this.opts.maxSize) return this.flush();
    if (!this.timer) this.timer = setTimeout(() => this.flush(), this.opts.flushMs);
  }
  flush() {
    if (this.timer) { clearTimeout(this.timer); this.timer = null; }
    if (!this.items.length) return;
    const batch = this.items; this.items = [];
    this.opts.onFlush(batch);
  }
  get size() { return this.items.length; }
}

export function cellularStep<T>(
  grid: T[][],
  neighborsOf: (r: number, c: number) => T[],
  nextCell: (cell: T, neighbors: T[], r: number, c: number) => T,
): T[][] {
  return grid.map((row, r) =>
    row.map((cell, c) => nextCell(cell, neighborsOf(r, c), r, c)),
  );
}

export function gameOfLifeStep(grid: number[][]): number[][] {
  const h = grid.length, w = grid[0]?.length ?? 0;
  function aliveNeighbors(r: number, c: number): number {
    let n = 0;
    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr === 0 && dc === 0) continue;
        const nr = (r + dr + h) % h, nc = (c + dc + w) % w;
        if (grid[nr][nc] === 1) n++;
      }
    }
    return n;
  }
  return grid.map((row, r) =>
    row.map((cell, c) => {
      const n = aliveNeighbors(r, c);
      return cell === 1 ? (n === 2 || n === 3 ? 1 : 0) : (n === 3 ? 1 : 0);
    }),
  );
}

