    ['Other', '', []],
  ];
  for (const c of commits) {
    const m = /^(feat|fix)(!)?: (.*)$/.exec(c.trim());
    if (!m) { cats[3][2].push(c.trim()); continue; }
    if (m[2]) cats[0][2].push(m[3]);
    else if (m[1] === 'feat') cats[1][2].push(m[3]);
    else cats[2][2].push(m[3]);
