export function jumpSearch(sorted: number[], target: number): number

export function jumpSearch(sorted: number[], target: number) {
  const n = sorted.length;
  const step = Math.floor(Math.sqrt(n));
  let prev = 0;
  while (prev < n && sorted[Math.min(step, n) - 1] < target) {
    prev = step;
    step += Math.floor(Math.sqrt(n));
    if (prev >= n) return -1;
  }
  for (let i = prev; i < Math.min(step, n); i++) if (sorted[i] === target) return i;
  return -1;
}

export function relativeTime(locale: string, deltaMs: number, opts?: Intl.RelativeTimeFormatOptions): string

const cache = new Map<string, Intl.RelativeTimeFormat>();
const UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ['year', 31536000000], ['month', 2592000000], ['week', 604800000],
  ['day', 86400000], ['hour', 3600000], ['minute', 60000], ['second', 1000],
];
export function relativeTime(locale: string, deltaMs: number, opts: Intl.RelativeTimeFormatOptions = { numeric: 'auto' }) {
  const key = locale + JSON.stringify(opts);
  if (!cache.has(key)) cache.set(key, new Intl.RelativeTimeFormat(locale, opts));
  for (const [unit, size] of UNITS) {
    const value = Math.round(deltaMs / size);
    if (Math.abs(value) >= 1 || unit === 'second') return cache.get(key)!.format(value, unit);
  }
  return cache.get(key)!.format(0, 'second');
}

const FENCE = '`'.repeat(3);
export function extractJson<T = unknown>(raw: string): T | null {
  const fenced = raw.match(new RegExp(`${FENCE}(?:json)?\\s*([\\s\\S]*?)${FENCE}`));
  const candidate = fenced ? fenced[1] : raw;
  const start = candidate.indexOf('{');
  if (start < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < candidate.length; i++) {
    const ch = candidate[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\' && inStr) { esc = true; continue; }
    if (ch === '"') inStr = !inStr;
    if (inStr) continue;
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) {
      try { return JSON.parse(candidate.slice(start, i + 1)) as T; } catch { return null; }
    } }
  }
  return null;
}

export async function retry<T>(fn: () => Promise<T>, opts?: { attempts?: number; baseMs?: number; maxMs?: number }): Promise<T>

export async function retry<T>(fn: () => Promise<T>, opts = {}) {
  const { attempts = 3, baseMs = 200, maxMs = 5000 } = opts;
  let lastErr: unknown;
  for (let i = 0; i < attempts; i++) {
    try { return await fn(); } catch (e) { lastErr = e; }
    if (i < attempts - 1) {
      const jitter = Math.random() * baseMs;
      await new Promise((r) => setTimeout(r, Math.min(maxMs, baseMs * 2 ** i + jitter)));
    }
  }
  throw lastErr;
}

export class SkipList {
  constructor(maxLevel?: number, p?: number)
  insert(key: number, value: unknown): void
  get(key: number): unknown | undefined
  remove(key: number): boolean
}

class SNode { next: (SNode | null)[] = []; constructor(public key: number, public value: unknown, level: number) { this.next = new Array(level).fill(null); } }
export class SkipList {
  private head: SNode;
  private level = 1;
  private p: number;
  constructor(private maxLevel = 16, p = 0.5) {
    this.head = new SNode(-Infinity, null, maxLevel);
    this.p = p;
  }
  private randLevel() { let l = 1; while (Math.random() < this.p && l < this.maxLevel) l++; return l; }
  insert(key: number, value: unknown) {
    const update = new Array(this.maxLevel).fill(this.head);
    let cur: SNode | null = this.head;
    for (let i = this.level - 1; i >= 0; i--) {
      while (cur!.next[i] && cur!.next[i]!.key < key) cur = cur!.next[i];
      update[i] = cur!;
    }
    cur = cur!.next[0];
    if (cur && cur.key === key) { cur.value = value; return; }
    const lvl = this.randLevel();
    if (lvl > this.level) {
      for (let i = this.level; i < lvl; i++) update[i] = this.head;
      this.level = lvl;
    }
    const node = new SNode(key, value, lvl);
    for (let i = 0; i < lvl; i++) { node.next[i] = update[i].next[i]; update[i].next[i] = node; }
  }
  get(key: number) {
    let cur: SNode | null = this.head;
    for (let i = this.level - 1; i >= 0; i--) while (cur!.next[i] && cur!.next[i]!.key < key) cur = cur!.next[i];
    cur = cur!.next[0];
    return cur && cur.key === key ? cur.value : undefined;
  }
  remove(key: number) {
    const update = new Array(this.maxLevel).fill(this.head);
    let cur: SNode | null = this.head;
    for (let i = this.level - 1; i >= 0; i--) {
      while (cur!.next[i] && cur!.next[i]!.key < key) cur = cur!.next[i];
      update[i] = cur!;
    }
    cur = cur!.next[0];
    if (!cur || cur.key !== key) return false;
    for (let i = 0; i < this.level; i++) if (update[i].next[i] === cur) update[i].next[i] = cur.next[i];
    while (this.level > 1 && !this.head.next[this.level - 1]) this.level--;
    return true;
  }
}

