export class WindowAggregator<T, A> {
  constructor(windowMs: number, fold: (acc: A, item: T) => A, init: A)
  add(item: T): A
  prune(now?: number): void
  get current(): A
}

export class WindowAggregator<T, A> {
  private items: Array<{ t: number; v: T }> = [];
  constructor(private windowMs: number, private fold: (acc: A, item: T) => A, private init: A) {}
  add(item: T) {
    this.items.push({ t: Date.now(), v: item });
    this.prune();
    return this.fold(this.items.slice().reverse().reduce((acc, i) => this.fold(acc, i.v), this.init), item) as A;
  }
  prune(now = Date.now()) {
    const cutoff = now - this.windowMs;
    this.items = this.items.filter((i) => i.t >= cutoff);
  }
  get current() { return this.items.reduce((acc, i) => this.fold(acc, i.v), this.init); }
}

export interface ParseCsvResult { headers: string[]; rows: Record<string, string>[] }
export function parseCsv(text: string, options?: { delimiter?: string }): ParseCsvResult

export function parseCsv(text: string, options?: { delimiter?: string }): ParseCsvResult {
  const delim = options?.delimiter ?? ',';
  const rows: string[][] = [];
  let row: string[] = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else inQuotes = false;
      } else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === delim) { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((f) => f.length > 0)) rows.push(row);
      row = [];
    } else field += c;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }

  const [headers, ...data] = rows;
  return { headers: headers ?? [], rows: data.map((r) => Object.fromEntries(headers.map((h, i) => [h, r[i] ?? '']))) };
}

export type DeltaPatch = Array<{ path: string; value: unknown }>
export function diffPaths(before: Record<string, unknown>, after: Record<string, unknown>): DeltaPatch
export function applyPatch(target: Record<string, unknown>, patch: DeltaPatch): Record<string, unknown>

export function diffPaths(before: Record<string, unknown>, after: Record<string, unknown>): DeltaPatch {
  const patch: DeltaPatch = [];
  const walk = (a: Record<string, unknown>, b: Record<string, unknown>, base: string) => {
    const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
    for (const k of keys) {
      const path = base ? `${base}.${k}` : k;
      const av = a[k], bv = b[k];
      if (JSON.stringify(av) === JSON.stringify(bv)) continue;
      if (av && bv && typeof av === 'object' && typeof bv === 'object' && !Array.isArray(av) && !Array.isArray(bv)) {
        walk(av as Record<string, unknown>, bv as Record<string, unknown>, path);
      } else {
        patch.push({ path, value: bv });
      }
    }
  };
  walk(before, after, '');
  return patch;
}
export function applyPatch(target: Record<string, unknown>, patch: DeltaPatch) {
  const out: Record<string, unknown> = JSON.parse(JSON.stringify(target));
  for (const { path, value } of patch) {
    const parts = path.split('.');
    let node = out;
    for (let i = 0; i < parts.length - 1; i++) node = node[parts[i]] as Record<string, unknown>;
    node[parts[parts.length - 1]] = value;
  }
  return out;
}

