export class RingBuffer<T> {
  constructor(capacity: number)
  push(item: T): void
  pop(): T | undefined
  get size(): number
  toArray(): T[]
}

export class RingBuffer<T> {
  private buf: Array<T | undefined>;
  private head = 0; private tail = 0; private count = 0;
  constructor(private capacity: number) { this.buf = new Array(capacity); }
  push(item: T) {
    if (this.count === this.capacity) { this.head = (this.head + 1) % this.capacity; this.count--; }
    this.buf[this.tail] = item;
    this.tail = (this.tail + 1) % this.capacity;
    this.count++;
  }
  pop() {
    if (!this.count) return undefined;
    const v = this.buf[this.head];
    this.head = (this.head + 1) % this.capacity;
    this.count--;
    return v;
  }
  get size() { return this.count; }
  toArray() {
    const out: T[] = [];
    for (let i = 0; i < this.count; i++) out.push(this.buf[(this.head + i) % this.capacity] as T);
    return out;
  }
}

export function indexTicks(count: number, maxLabels: number): number[]

export function indexTicks(count: number, maxLabels: number) {
  if (count <= maxLabels) return Array.from({ length: count }, (_, i) => i);
  const step = Math.ceil(count / maxLabels);
  const out: number[] = [];
  for (let i = 0; i < count; i += step) out.push(i);
  if (out[out.length - 1] !== count - 1) out.push(count - 1);
  return out;
}

