export async function fetchWithRetry(
  input: RequestInfo | URL,
  init?: RequestInit,
  options?: { attempts?: number; backoffMs?: number; retryStatuses?: number[] },
): Promise<Response> {
  const attempts = options?.attempts ?? 3;
  const backoff = options?.backoffMs ?? 300;
  const retryStatuses = options?.retryStatuses ?? [408, 429, 500, 502, 503, 504];

  for (let i = 0; i < attempts; i++) {
    try {
      const res = await fetch(input, init);
      if (!retryStatuses.includes(res.status) || i === attempts - 1) return res;
      await new Promise((r) => setTimeout(r, backoff * 2 ** i));
    } catch (e) {
      if (i === attempts - 1) throw e;
      await new Promise((r) => setTimeout(r, backoff * 2 ** i));
    }
  }
  throw new Error('unreachable');
}

export interface QueuedJob<T = unknown> { id: string; payload: T; attempts: number; status: 'queued' | 'running' | 'done' | 'failed'; error?: string }
export function createJobQueue<T = unknown>(
  worker: (payload: T) => Promise<void>,
  storage?: StorageAdapter<QueuedJob<T>[]>,
  options?: { maxAttempts?: number },
) {
  return {
    enqueue(payload: T): string,
    get size(): number,
    start(): void,
    stop(): void,
    statusOf(id: string): QueuedJob<T> | undefined,
  };
}

export function createJobQueue<T = unknown>(
  worker: (payload: T) => Promise<void>,
  storage?: StorageAdapter<QueuedJob<T>[]>,
  options?: { maxAttempts?: number },
) {
  const maxAttempts = options?.maxAttempts ?? 3;
  const jobs = new Map<string, QueuedJob<T>>();
  const order: string[] = [];
  let running = false;
  let started = false;

  if (storage) {
    const saved = storage.load() ?? [];
    for (const j of saved) if (j.status === 'queued' || j.status === 'failed') { jobs.set(j.id, { ...j, status: 'queued' }); order.push(j.id); }
  }

  function persist() {
    storage?.save([...jobs.values()]);
  }

  async function pump() {
    if (running || !started) return;
    running = true;
    while (order.length > 0 && started) {
      const id = order.shift()!;
      const job = jobs.get(id);
      if (!job || job.status === 'done') continue;
      job.status = 'running';
      persist();
      try {
        await worker(job.payload);
        job.status = 'done';
      } catch (e) {
        job.attempts++;
        job.error = (e as Error).message;
        if (job.attempts >= maxAttempts) job.status = 'failed';
        else { job.status = 'queued'; order.push(id); }
      }
      persist();
    }
    running = false;
  }

  return {
    enqueue(payload) {
      const id = crypto.randomUUID();
      jobs.set(id, { id, payload, attempts: 0, status: 'queued' });
      order.push(id);
      persist();
      void pump();
      return id;
    },
    get size() { return order.length; },
    start() { started = true; void pump(); },
    stop() { started = false; },
    statusOf(id) { return jobs.get(id); },
  };
}

