const RTL_RE = /[\u0590-\u08FF\uFB1D-\uFDFD\uFE70-\uFEFC]/;
const LTR_RE = /[A-Za-z0-9\u00C0-\u02AF\u0370-\u03FF\u0400-\u04FF\u0530-\u058F\u0600-\u06FF\u0E00-\u0E7F]/;
