export function makeGraphQLServer(typeDefs: string, resolvers: GraphQLResolvers) {
  return async (
    query: string,
    variables: Record<string, unknown> = {},
    ctx: unknown,
  ): Promise<{ data?: unknown; errors?: unknown[] }> => {
    const fieldMatch = query.match(/\{(\s*[a-zA-Z_]+)/);
    const field = fieldMatch ? fieldMatch[1].trim() : null;
    if (!field) return { errors: [{ message: 'no_field' }] };
    const fn = resolvers.Query?.[field] ?? resolvers.Mutation?.[field];
    if (!fn) return { errors: [{ message: `unknown_field:${field}` }] };
    try {
      const data = await fn(null, variables, ctx);
      return { data: { [field]: data } };
    } catch (e) {
      return { errors: [{ message: (e as Error).message }] };
    }
  };
}

export function createUndoStack<T>(limit?: number) {
  return {
    push(snapshot: T): void,
    undo(): T | null,
    redo(): T | null,
    get canUndo(): boolean,
    get canRedo(): boolean,
    clear(): void,
  };
}

export function createUndoStack<T>(limit = 100) {
  const past: T[] = [];
  const future: T[] = [];
  let current: T | null = null;

  return {
    push(snapshot: T) {
      if (current !== null) {
        past.push(current);
        if (past.length > limit) past.shift();
      }
      current = snapshot;
      future.length = 0;
    },
    undo() {
      if (past.length === 0) return null;
      if (current !== null) future.push(current);
      current = past.pop()!;
      return current;
    },
    redo() {
      if (future.length === 0) return null;
      if (current !== null) past.push(current);
      current = future.pop()!;
      return current;
    },
    get canUndo() { return past.length > 0; },
    get canRedo() { return future.length > 0; },
    clear() { past.length = 0; future.length = 0; current = null; },
  };
}

