}

export function expandMatrix(matrix: Record<string, string[]>): Array<Record<string, string>>

export function expandMatrix(matrix: Record<string, string[]>) {
  const keys = Object.keys(matrix);
  if (!keys.length) return [{}];
  const out: Array<Record<string, string>> = [];
  const walk = (idx: number, acc: Record<string, string>) => {
    if (idx === keys.length) { out.push({ ...acc }); return; }
    for (const v of matrix[keys[idx]]) walk(idx + 1, { ...acc, [keys[idx]]: v });
  };
  walk(0, {});
  return out;
}

export interface TreeNode<T> { value: T; children: TreeNode<T>[] }
export function walk<T>(root: TreeNode<T>, visit: (n: TreeNode<T>, depth: number) => void): void

export function walk<T>(root: TreeNode<T>, visit: (n: TreeNode<T>, depth: number) => void) {
  const go = (n: TreeNode<T>, d: number) => {
    visit(n, d);
    n.children.forEach((c) => go(c, d + 1));
  };
  go(root, 0);
}

export function interleave(...strings: string[]) {
  const cols = strings.map((s) => Array.from(s));
  const max = Math.max(...cols.map((c) => c.length), 0);
  const out: string[] = [];
  for (let i = 0; i < max; i++) for (const col of cols) if (i < col.length) out.push(col[i]);
  return out.join('');
}

export function renderTree(paths: string[]) {
  const root: Record<string, unknown> = {};
  for (const p of paths) {
    let node = root;
    for (const part of p.split('/')) {
      if (part === '') continue;
      if (typeof node[part] !== 'object' || node[part] === null) node[part] = {};
      node = node[part] as Record<string, unknown>;
    }
  }
  const lines: string[] = [];
  const walk = (node: Record<string, unknown>, prefix: string, isRoot: boolean) => {
    const keys = Object.keys(node).sort();
    keys.forEach((k, i) => {
      const last = i === keys.length - 1;
      lines.push(prefix + (last ? '`- ' : '|- ') + k);
      walk(node[k] as Record<string, unknown>, prefix + (last ? '   ' : '|  '), false);
    });
  };
  walk(root, '', true);
  return lines.join('\n');
}

export function uniqueName(base: string, existing: Set<string>) {
  if (!existing.has(base)) return base;
  let i = 2;
