const MUTATIONS = ['', ' ', '\n', '\r\n', '\t', '"', "'", '<script>', '../', '\\', 'null', 'undefined', 'NaN', '%00', '`', ';', '{}', '[]', '\\u0000', '❌', 'A'.repeat(1000)];
export function fuzzInputs(base: string, count = 50) {
  const out: string[] = [];
  out.push(base);
  for (let i = 0; i < count; i++) {
    const m = MUTATIONS[i % MUTATIONS.length];
    const pos = (i * 7) % (base.length + 1);
    out.push(base.slice(0, pos) + m + base.slice(pos));
  }
  return out;
}

export function trapezoid(f: (x: number) => number, a: number, b: number, n = 1000) {
  const h = (b - a) / n;
  let s = (f(a) + f(b)) / 2;
  for (let i = 1; i < n; i++) s += f(a + i * h);
  return s * h;
}
export function simpson(f: (x: number) => number, a: number, b: number, n = 1000) {
  const nn = n % 2 === 0 ? n : n + 1;
  const h = (b - a) / nn;
  let s = f(a) + f(b);
  for (let i = 1; i < nn; i++) s += f(a + i * h) * (i % 2 === 0 ? 2 : 4);
  return (s * h) / 3;
}

