export async function copyText(text: string) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    try {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand('copy');
      ta.remove();
      return ok;
    } catch {
      return false;
    }
  }
}

export class GaussianNaiveBayes {
  fit(samples: { x: number[]; label: string }[]): void
  predict(x: number[]): string
}

export class GaussianNaiveBayes {
  private classes: Map<string, { mean: number[]; var: number[]; prior: number }> = new Map();
  fit(samples: { x: number[]; label: string }[]) {
    const byLabel = new Map<string, number[][]>();
    for (const s of samples) {
      if (!byLabel.has(s.label)) byLabel.set(s.label, []);
      byLabel.get(s.label)!.push(s.x);
    }
    const n = samples.length;
    for (const [label, xs] of byLabel) {
      const dim = xs[0].length;
      const mean = Array.from({ length: dim }, (_, d) =>
        xs.reduce((s, x) => s + x[d], 0) / xs.length);
      const variance = Array.from({ length: dim }, (_, d) =>
        xs.reduce((s, x) => s + (x[d] - mean[d]) ** 2, 0) / xs.length);
      this.classes.set(label, { mean, var: variance.map((v) => v + 1e-9), prior: xs.length / n });
    }
  }
  predict(x: number[]) {
    let best = '', bestScore = -Infinity;
    for (const [label, c] of this.classes) {
      let score = Math.log(c.prior);
      for (let d = 0; d < x.length; d++) {
        const diff = x[d] - c.mean[d];
        score -= 0.5 * (Math.log(2 * Math.PI * c.var[d]) + (diff * diff) / c.var[d]);
      }
      if (score > bestScore) { bestScore = score; best = label; }
    }
    return best;
  }
}

export interface RetrieverDoc { id: string; text: string; vector: number[] }
export function retrieveTopK(query: number[], docs: RetrieverDoc[], k = 3): Array<{ doc: RetrieverDoc; score: number }>

function cosine(a: number[], b: number[]) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) || 1);
}
export function retrieveTopK(query: number[], docs: RetrieverDoc[], k = 3) {
  return docs
    .map((doc) => ({ doc, score: cosine(query, doc.vector) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, k);
}

export function fleschReadingEase(words: number, sentences: number, syllables: number): number

export function fleschReadingEase(words: number, sentences: number, syllables: number) {
  if (!words || !sentences) return 0;
  return Math.max(0, Math.min(100, 206.835 - 1.015 * (words / sentences) - 84.6 * (syllables / words)));
}

export class SparseMatrix {
  constructor(rows: number, cols: number)
  set(r: number, c: number, v: number): void
  get(r: number, c: number): number
  get size(): { rows: number; cols: number; nonZero: number }
}

export class SparseMatrix {
  private data = new Map<string, number>();
  constructor(private rows: number, private cols: number) {}
  private key(r: number, c: number) { return r + ',' + c; }
  set(r: number, c: number, v: number) {
    if (r < 0 || r >= this.rows || c < 0 || c >= this.cols) throw new Error('Out of bounds');
    if (v === 0) this.data.delete(this.key(r, c));
    else this.data.set(this.key(r, c), v);
  }
  get(r: number, c: number) { return this.data.get(this.key(r, c)) ?? 0; }
  get size() { return { rows: this.rows, cols: this.cols, nonZero: this.data.size }; }
}

export function banner(title: string, width = 60) {
  const inner = ` ${title} `;
  if (inner.length >= width) return title;
  const pad = width - inner.length;
  const left = Math.floor(pad / 2), right = pad - left;
  return '='.repeat(left) + inner + '='.repeat(right);
}

export interface LoadedLevel { width: number; height: number; grid: string[][]; playerStart?: [number, number]; entities: Array<{ type: string; x: number; y: number }> }
export function loadAsciiLevel(ascii: string, legend: Record<string, string>): LoadedLevel

export function loadAsciiLevel(ascii: string, legend: Record<string, string>): LoadedLevel {
  const lines = ascii.trim().split('\n').map((l) => l.trim()).filter(Boolean);
  const grid = lines.map((line) => [...line].map((ch) => legend[ch] ?? 'empty'));
  const height = grid.length;
  const width = grid[0]?.length ?? 0;

  const entities: LoadedLevel['entities'] = [];
  let playerStart: [number, number] | undefined;

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const ch = lines[y][x];
      if (ch === 'P') playerStart = [x, y];
      if (ch !== '.' && ch !== '#' && ch !== 'P') entities.push({ type: ch, x, y });
    }
  }

  return { width, height, grid, playerStart, entities };
}

export class SessionStore<T> {
  constructor(private key: string, private version: number, private store: { load: () => string | null; save: (s: string) => void } = {
    load: () => localStorage.getItem(key),
    save: (s) => localStorage.setItem(key, s),
  }) {}
  restore(): T | null {
    try {
      const raw = this.store.load();
      if (!raw) return null;
      const parsed = JSON.parse(raw) as SessionState<T>;
      return parsed.version === this.version ? parsed.data : null;
    } catch { return null; }
  }
  save(data: T) { this.store.save(JSON.stringify({ version: this.version, data, savedAt: Date.now() })); }
  clear() { this.store.save(''); }
}

export function formatSse(event: string, data: unknown, id?: number): string {
  const parts: string[] = [];
  if (id !== undefined) parts.push(`id: ${id}`);
  parts.push(`event: ${event}`);
  const json = JSON.stringify(data);
  parts.push(`data: ${json.replace(/\n/g, '\ndata: ')}`);
