export function testMatrix<T extends Record<string, unknown>>(dimensions: Record<string, unknown[]>): Array<{ name: string; values: T }>

export function testMatrix<T extends Record<string, unknown>>(dimensions: Record<string, unknown[]>) {
  const keys = Object.keys(dimensions);
  const out: Array<{ name: string; values: T }> = [];
  const walk = (idx: number, acc: Record<string, unknown>, parts: string[]) => {
    if (idx === keys.length) { out.push({ name: parts.join(' | ') || 'default', values: acc as T }); return; }
    for (const v of dimensions[keys[idx]]) walk(idx + 1, { ...acc, [keys[idx]]: v }, [...parts, `${keys[idx]}=${JSON.stringify(v)}`]);
  };
  walk(0, {}, []);
  return out;
}

export function samplingConfig(opts?: Partial<SamplingConfig>): SamplingConfig {
