}

export function formatBytes(bytes: number, decimals = 1) {
  if (!Number.isFinite(bytes) || bytes < 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
  let i = 0, v = bytes;
  while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }
  return `${v.toFixed(i === 0 ? 0 : decimals)} ${units[i]}`;
}

export function createCamera(options?: { width?: number; height?: number; lerp?: number }) {
  return {
    x: number; y: number;
    follow(target: { x: number; y: number }, bounds?: { minX: number; minY: number; maxX: number; maxY: number }): void,
    worldToScreen(wx: number, wy: number): [number, number],
    screenToWorld(sx: number, sy: number): [number, number],
  };
}

export function createCamera(options?: { width?: number; height?: number; lerp?: number }) {
  const width = options?.width ?? 800;
  const height = options?.height ?? 600;
  const lerp = options?.lerp ?? 0.12;
  const cam = { x: 0, y: 0 };

  return {
    get x() { return cam.x; },
    get y() { return cam.y; },
    follow(target, bounds) {
      const desiredX = target.x - width / 2;
      const desiredY = target.y - height / 2;
      cam.x += (desiredX - cam.x) * lerp;
      cam.y += (desiredY - cam.y) * lerp;
      if (bounds) {
        cam.x = Math.max(bounds.minX, Math.min(bounds.maxX - width, cam.x));
        cam.y = Math.max(bounds.minY, Math.min(bounds.maxY - height, cam.y));
      }
    },
    worldToScreen(wx, wy) { return [wx - cam.x, wy - cam.y]; },
    screenToWorld(sx, sy) { return [sx + cam.x, sy + cam.y]; },
  };
}

export function localeSort(items: string[], locale: string, desc = false) {
  const cmp = localeCompareFn(locale);
  return items.slice().sort((a, b) => (desc ? -1 : 1) * cmp(a, b));
}

export interface AudioMetadata { duration: number; title?: string; artist?: string; album?: string }
export async function readAudioMetadata(blob: Blob): Promise<AudioMetadata>
export function parseId3Tags(bytes: Uint8Array): { title?: string; artist?: string; album?: string }

export function parseId3Tags(bytes: Uint8Array): { title?: string; artist?: string; album?: string } {
  // Minimal ID3v2.3/v2.4 frame scan: 'TIT2' title, 'TPE1' artist, 'TALB' album.
  if (bytes.length < 10 || String.fromCharCode(bytes[0], bytes[1], bytes[2]) !== 'ID3') return {};
  const major = bytes[3];
  const size = ((bytes[6] & 0x7f) << 21) | ((bytes[7] & 0x7f) << 14) | ((bytes[8] & 0x7f) << 7) | (bytes[9] & 0x7f);
  const out: { title?: string; artist?: string; album?: string } = {};
  let pos = 10;
  const end = Math.min(bytes.length, 10 + size);

  function readFrameSize(b: Uint8Array, i: number): number {
    if (major >= 4) {
      return ((b[i] & 0x7f) << 21) | ((b[i + 1] & 0x7f) << 14) | ((b[i + 2] & 0x7f) << 7) | (b[i + 3] & 0x7f);
    }
    return (b[i] << 24) | (b[i + 1] << 16) | (b[i + 2] << 8) | b[i + 3];
  }

  function readFrame(): { id: string; data: string } | null {
    if (pos + 10 > end) return null;
    const id = String.fromCharCode(...bytes.subarray(pos, pos + 4));
    const frameSize = readFrameSize(bytes, pos + 4);
    pos += 10;
    if (pos + frameSize > end) return null;
    const raw = bytes.subarray(pos, pos + frameSize);
    pos += frameSize;
    // Text frames: first byte is encoding, then UTF-16 (BOM) or Latin-1 text.
    let text = '';
    if (raw[0] === 1 && raw.length >= 3) {
      const bom = (raw[1] << 8) | raw[2];
      if (bom === 0xfffe) text = new TextDecoder('utf-16le').decode(raw.subarray(3));
      else if (bom === 0xfeff) text = new TextDecoder('utf-16be').decode(raw.subarray(3));
    } else if (raw[0] === 0) {
      text = new TextDecoder('latin1').decode(raw.subarray(1));
    }
    return { id, data: text.replace(/\0/g, '').trim() };
  }

  let frame = readFrame();
  while (frame) {
    if (frame.id === 'TIT2') out.title = frame.data;
    else if (frame.id === 'TPE1') out.artist = frame.data;
    else if (frame.id === 'TALB') out.album = frame.data;
    frame = readFrame();
  }
  return out;
}

export async function readAudioMetadata(blob: Blob): Promise<AudioMetadata> {
  const ctx = new AudioContext();
  try {
    const bytes = new Uint8Array(await blob.arrayBuffer());
    const tags = parseId3Tags(bytes);
    const ab = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
    const decoded = await ctx.decodeAudioData(ab);
    return { duration: decoded.duration, ...tags };
  } finally {
    await ctx.close();
  }
}

export function mixReview<T>(due: T[], fresh: T[], dailyNewCap: number) {
  const out: T[] = [];
  const d = due.slice(), f = fresh.slice(0, dailyNewCap);
  while (d.length || f.length) {
    if (d.length) out.push(d.shift()!);
    if (f.length) out.push(f.shift()!);
  }
  return out;
}

