export interface DiffStat { file: string; added: number; removed: number }
export function diffSummary(unifiedDiff: string): DiffStat[]

export function diffSummary(unifiedDiff: string) {
  const stats: DiffStat[] = [];
  let cur: DiffStat | null = null;
  for (const line of unifiedDiff.split('\n')) {
    if (line.startsWith('+++ ')) {
      const file = line.slice(4).trim();
      cur = { file, added: 0, removed: 0 };
      stats.push(cur);
    } else if (cur) {
      if (line.startsWith('+')) cur.added++;
      else if (line.startsWith('-')) cur.removed++;
    }
  }
  return stats;
}

export function setViewportZoom(scale: number, userScalable?: boolean): void
export function restoreViewport(): void

let prev = '';
export function setViewportZoom(scale: number, userScalable = false) {
  const vp = document.querySelector('meta[name="viewport"]');
  if (vp) { prev = vp.getAttribute('content') ?? ''; vp.setAttribute('content', `width=device-width, initial-scale=${scale}, maximum-scale=${scale}, user-scalable=${userScalable ? 'yes' : 'no'}`); }
}
export function restoreViewport() {
  const vp = document.querySelector('meta[name="viewport"]');
  if (vp && prev) vp.setAttribute('content', prev);
}

import * as fs from 'fs/promises';

export function createLockFile(lockPath: string) {
  return {
    async acquire(staleMs = 60_000): Promise<boolean> {
      try {
        const fd = await fs.open(lockPath, 'wx');
        await fd.writeFile(JSON.stringify({ pid: process.pid, at: Date.now() }));
        await fd.close();
        return true;
      } catch {
        // Lock exists — check staleness.
        try {
          const raw = await fs.readFile(lockPath, 'utf-8');
          const meta = JSON.parse(raw) as { pid: number; at: number };
          if (Date.now() - meta.at > staleMs) {
            await fs.unlink(lockPath).catch(() => {});
            return this.acquire(staleMs);
          }
        } catch { /* unreadable — treat as stale */ }
        return false;
      }
    },
    async release() {
      await fs.unlink(lockPath).catch(() => {});
    },
    async isLocked() {
      try { await fs.access(lockPath); return true; } catch { return false; }
    },
  };
}

