export interface ResizeOptions { maxWidth?: number; maxHeight?: number; mode?: 'cover' | 'contain'; quality?: number; format?: 'image/jpeg' | 'image/png' | 'image/webp' }
export async function resizeImage(source: HTMLImageElement | Blob, options?: ResizeOptions): Promise<string>

export async function resizeImage(source: HTMLImageElement | Blob, options: ResizeOptions = {}): Promise<string> {
  const img = source instanceof Blob
    ? await createImageBitmap(source)
    : source;

  const srcW = 'width' in img ? img.width : 0;
  const srcH = 'height' in img ? img.height : 0;
  const maxW = options.maxWidth ?? srcW;
  const maxH = options.maxHeight ?? srcH;

  let scale = Math.min(maxW / srcW, maxH / srcH);
  if (options.mode === 'cover') scale = Math.max(maxW / srcW, maxH / srcH);
  scale = Math.min(1, scale);   // only downscale by default

  const w = Math.max(1, Math.round(srcW * scale));
  const h = Math.max(1, Math.round(srcH * scale));

  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d')!;
  ctx.drawImage(img as CanvasImageSource, 0, 0, w, h);

  const format = options.format ?? 'image/jpeg';
  return canvas.toDataURL(format, options.quality ?? 0.85);
}

export function mapRow<T>(row: Record<string, unknown>, rename?: Record<string, keyof T>): T

export function mapRow<T>(row: Record<string, unknown>, rename?: Record<string, keyof T>) {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(row)) {
    const key = rename?.[k] ?? k.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());
    out[String(key)] = v;
  }
  return out as T;
}

export async function retryTest(fn: () => Promise<void>, attempts = 3) {
  let last: unknown;
  for (let i = 0; i < attempts; i++) {
    try { await fn(); return; } catch (e) { last = e; }
  }
  throw last;
}

