export class CursorTracker {
  constructor(expiryMs?: number)
  move(userId: string, pos: { x: number; y: number }, meta?: Record<string, unknown>): void
  prune(): string[]
  get cursors(): Array<{ userId: string; x: number; y: number; meta?: Record<string, unknown> }>
}

export class CursorTracker {
  private map = new Map<string, { x: number; y: number; t: number; meta?: Record<string, unknown> }>();
  constructor(private expiryMs = 15000) {}
  move(userId: string, pos: { x: number; y: number }, meta?: Record<string, unknown>) {
    this.map.set(userId, { x: pos.x, y: pos.y, t: Date.now(), meta });
  }
  prune() {
    const now = Date.now();
    const gone: string[] = [];
    for (const [id, c] of this.map) if (now - c.t > this.expiryMs) { this.map.delete(id); gone.push(id); }
    return gone;
  }
  get cursors() {
    this.prune();
    return [...this.map.entries()].map(([userId, c]) => ({ userId, x: c.x, y: c.y, meta: c.meta }));
  }
}

export function rankByCosine(query: number[], candidates: Array<{ id: string; vector: number[] }>, k?: number): Array<{ id: string; score: number }>

export function rankByCosine(query: number[], candidates: Array<{ id: string; vector: number[] }>, k?: number) {
  const scored = candidates.map((c) => {
    let dot = 0, na = 0, nb = 0;
    for (let i = 0; i < query.length; i++) { dot += query[i] * c.vector[i]; na += query[i] ** 2; nb += c.vector[i] ** 2; }
    return { id: c.id, score: dot / (Math.sqrt(na) * Math.sqrt(nb) || 1) };
  }).sort((a, b) => b.score - a.score);
  return k ? scored.slice(0, k) : scored;
}

export function mergesort<T>(items: T[], compare?: (a: T, b: T) => number): T[] {
  const cmp = compare ?? ((a: T, b: T) => (a < b ? -1 : a > b ? 1 : 0));

  function merge(left: T[], right: T[]): T[] {
    const out: T[] = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length) {
      if (cmp(left[i], right[j]) <= 0) out.push(left[i++]);
      else out.push(right[j++]);
    }
    return out.concat(left.slice(i), right.slice(j));
  }

  function sort(arr: T[]): T[] {
    if (arr.length <= 1) return arr;
    const mid = arr.length >> 1;
    return merge(sort(arr.slice(0, mid)), sort(arr.slice(mid)));
  }

  return sort([...items]);
}

