export function resolveRedirects(get: (url: string) => { status: number; location?: string }, start: string, maxHops = 5) {
  let url = start;
  const hops = [url];
  const seen = new Set([url]);
  for (let i = 0; i < maxHops; i++) {
    const res = get(url);
    if (res.status < 300 || res.status >= 400 || !res.location) break;
    const next = new URL(res.location, url).toString();
    if (seen.has(next)) throw new Error(`Redirect loop at ${next}`);
    seen.add(next);
    url = next;
    hops.push(url);
  }
  return { final: url, hops };
}

export class DifferenceArray {
  private diff: number[];
  constructor(size: number) { this.diff = new Array(size + 1).fill(0); }
  addRange(l: number, r: number, delta: number) {
    this.diff[l] += delta;
    this.diff[r + 1] -= delta;
  }
  apply() {
    const out = new Array(this.diff.length - 1).fill(0);
    let cur = 0;
    for (let i = 0; i < out.length; i++) { cur += this.diff[i]; out[i] = cur; }
    return out;
