export function aesDecrypt(result: AesEncryptResult, key: Buffer): string {
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(result.iv, 'base64'));
  decipher.setAuthTag(Buffer.from(result.tag, 'base64'));
  const decrypted = Buffer.concat([
    decipher.update(Buffer.from(result.ciphertext, 'base64')),
    decipher.final(),
  ]);
  return decrypted.toString('utf8');
}

export function mean(values: number[]) { return values.length ? values.reduce((s, v) => s + v, 0) / values.length : NaN; }
export function variance(values: number[], sample = true) {
  if (values.length < 2) return NaN;
  const m = mean(values);
  const ss = values.reduce((s, v) => s + (v - m) ** 2, 0);
  return ss / (values.length - (sample ? 1 : 0));
}
export function stdDev(values: number[], sample = true) { return Math.sqrt(variance(values, sample)); }
export function median(values: number[]) {
  const s = [...values].sort((a, b) => a - b);
  const n = s.length;
  return n === 0 ? NaN : n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2;
}

