export function negotiateLocale(acceptLanguage: string, supported: string[], defaultLocale: string) {
  const parsed = acceptLanguage.split(',').map((p) => {
    const [tag, ...params] = p.trim().split(';');
    const q = parseFloat(params.find((x) => x.trim().startsWith('q='))?.split('=')[1] ?? '1');
    return { tag: tag.trim(), q: isNaN(q) ? 0 : q };
  }).sort((a, b) => b.q - a.q);
  for (const { tag } of parsed) {
    const exact = supported.find((s) => s.toLowerCase() === tag.toLowerCase());
    if (exact) return exact;
    const lang = tag.split('-')[0].toLowerCase();
    const partial = supported.find((s) => s.split('-')[0].toLowerCase() === lang);
    if (partial) return partial;
  }
  return defaultLocale;
}

export function createInMemoryRepository<T extends Entity>(): Repository<T> {
  const rows = new Map<string, T>();

  return {
    async findAll() { return [...rows.values()]; },
    async find(id) { return rows.get(id) ?? null; },
    async create(item) { rows.set(item.id, item); return item; },
    async update(id, patch) {
      const existing = rows.get(id);
      if (!existing) return null;
      const next = { ...existing, ...patch, id };
      rows.set(id, next);
      return next;
    },
    async remove(id) { return rows.delete(id); },
  };
}

export function evaluateConditional(etag: string | undefined, lastModifiedMs: number | undefined, headers: Record<string, string>) {
  const inm = headers['if-none-match'];
  if (inm !== undefined && etag !== undefined) {
    const tags = inm.split(',').map((t) => t.trim().replace(/^W\//, ''));
    if (tags.includes('*') || tags.includes(etag.replace(/^W\//, ''))) return true;
  }
  const ims = headers['if-modified-since'];
  if (ims !== undefined && lastModifiedMs !== undefined) {
    const since = Date.parse(ims);
    if (!isNaN(since) && lastModifiedMs <= since) return true;
  }
  return false;
}

