export async function daemonize(options?: { pidFile?: string; logFile?: string; cwd?: string }): Promise<void> {
  // Fork the current process detached so it survives the parent's exit.
  const { spawn } = await import('child_process');
  const args = process.argv.slice(2);
  const child = spawn(process.execPath, [process.argv[1], ...args], {
    detached: true,
    stdio: options?.logFile
      ? ['ignore', fs.openSync(options.logFile, 'a'), fs.openSync(options.logFile, 'a')]
      : 'ignore',
    cwd: options?.cwd,
    env: process.env,
  });
  child.unref();

  if (options?.pidFile) {
    await fs.promises.mkdir(path.dirname(options.pidFile), { recursive: true });
    await fs.promises.writeFile(options.pidFile, String(child.pid));
  }
}

export function registerGracefulShutdown(
  cleanup: () => Promise<void> | void,
  options?: { timeoutMs?: number; onSignal?: (signal: string) => void },
): { shutdown(signal: string): Promise<void>; unregister(): void }

export function registerGracefulShutdown(
  cleanup: () => Promise<void> | void,
  options?: { timeoutMs?: number; onSignal?: (signal: string) => void },
) {
  let shuttingDown = false;

  async function shutdown(signal: string) {
    if (shuttingDown) return;
    shuttingDown = true;
    options?.onSignal?.(signal);
    const force = setTimeout(() => {
      console.error(`[shutdown] forced exit after ${options?.timeoutMs ?? 10_000}ms`);
      process.exit(1);
    }, options?.timeoutMs ?? 10_000);
    force.unref();
    try { await cleanup(); } finally { clearTimeout(force); process.exit(0); }
  }

  const onSigint = () => void shutdown('SIGINT');
  const onSigterm = () => void shutdown('SIGTERM');
  process.on('SIGINT', onSigint);
  process.on('SIGTERM', onSigterm);

  return {
    shutdown,
    unregister() {
      process.removeListener('SIGINT', onSigint);
      process.removeListener('SIGTERM', onSigterm);
    },
  };
}

export class ListZipper<T> {
  private left: T[] = [];
  private right: T[];
  constructor(items: T[], index = 0) {
    const safe = Math.max(0, Math.min(index, items.length));
    this.left = items.slice(0, safe);
    this.right = items.slice(safe);
  }
  get current() { return this.right[0]; }
  move(delta: number) {
    while (delta > 0 && this.right.length > 1) { this.left.push(this.right.shift()!); delta--; }
    while (delta < 0 && this.left.length) { this.right.unshift(this.left.pop()!); delta++; }
    return this.current;
  }
  insert(item: T) { this.right.unshift(item); }
  remove() {
    if (!this.right.length) return undefined;
    const [head, ...rest] = this.right;
    this.right = rest;
    return head;
  }
}

export function createBloomFilter(size?: number, hashCount?: number) {
  return {
    add(item: string): void,
    has(item: string): boolean,     // true = maybe present
    clear(): void,
    get usedBits(): number,
  };
}

function fnv1a(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return h >>> 0;
}

export function createBloomFilter(size = 256, hashCount = 3) {
  const bits = new Uint8Array(Math.ceil(size / 8));
  let used = 0;

  function indexes(item: string): number[] {
    const a = fnv1a(item);
    const b = fnv1a('salt:' + item);
    return Array.from({ length: hashCount }, (_, i) => (a + i * b) % size);
  }

  return {
    add(item) {
      for (const i of indexes(item)) {
        const byte = i >> 3, mask = 1 << (i & 7);
        if (!(bits[byte] & mask)) { bits[byte] |= mask; used++; }
      }
    },
    has(item) {
      for (const i of indexes(item)) {
        if (!(bits[i >> 3] & (1 << (i & 7)))) return false;
      }
      return true;
    },
    clear() { bits.fill(0); used = 0; },
    get usedBits() { return used; },
  };
}

export interface AchievementDef { id: string; name: string; description: string; condition: (stats: Record<string, number>) => boolean }
export function createAchievementTracker(defs: AchievementDef[], onUnlock?: (id: string) => void) {
  return {
    updateStats(stats: Record<string, number>): string[],
    unlock(id: string): boolean,
    get unlocked(): Set<string>,
    get progress(): Array<{ id: string; unlocked: boolean; condition: string }>,
  };
}

export function createAchievementTracker(defs: AchievementDef[], onUnlock?: (id: string) => void) {
  const unlocked = new Set<string>();
  let stats: Record<string, number> = {};

  return {
    updateStats(next: Record<string, number>) {
      stats = { ...stats, ...next };
      const fresh: string[] = [];
      for (const def of defs) {
        if (!unlocked.has(def.id) && def.condition(stats)) {
          unlocked.add(def.id);
          fresh.push(def.id);
          onUnlock?.(def.id);
        }
      }
      return fresh;
    },
    unlock(id) {
      if (unlocked.has(id)) return false;
      if (!defs.some((d) => d.id === id)) return false;
      unlocked.add(id);
      onUnlock?.(id);
      return true;
    },
    get unlocked() { return new Set(unlocked); },
    get progress() {
      return defs.map((d) => ({ id: d.id, unlocked: unlocked.has(d.id), condition: d.description }));
    },
  };
}

