export type PinKind = 'exact' | 'caret' | 'tilde' | 'range' | 'wildcard' | 'invalid'
export function pinKind(spec: string): PinKind

export function pinKind(spec: string): PinKind {
  const s = spec.trim();
  if (!s || !/^[\^~<>=0-9.*xX\s|-]+$/.test(s)) return 'invalid';
  if (/^\d+\.\d+\.\d+$/.test(s)) return 'exact';
  if (/^\^/.test(s)) return 'caret';
  if (/^~/.test(s)) return 'tilde';
  if (/^[<>=]/.test(s) || s.includes(' - ') || s.includes('||')) return 'range';
  if (/[*xX]/.test(s)) return 'wildcard';
  return 'invalid';
}

export function maxFlow(n: number, edges: Array<[number, number, number]>, s: number, t: number) {
  const cap: number[][] = Array.from({ length: n }, () => new Array(n).fill(0));
  for (const [u, v, c] of edges) cap[u][v] += c;
  let flow = 0;
  while (true) {
    const parent = new Array(n).fill(-1);
    const queue = [s];
    parent[s] = s;
    while (queue.length && parent[t] === -1) {
      const u = queue.shift()!;
      for (let v = 0; v < n; v++) if (parent[v] === -1 && cap[u][v] > 0) { parent[v] = u; queue.push(v); }
    }
    if (parent[t] === -1) break;
    let push = Infinity;
    for (let v = t; v !== s; v = parent[v]) push = Math.min(push, cap[parent[v]][v]);
    for (let v = t; v !== s; v = parent[v]) { cap[parent[v]][v] -= push; cap[v][parent[v]] += push; }
    flow += push;
  }
  return flow;
}

