export function trapFocus(container: HTMLElement) {
  const prev = document.activeElement as HTMLElement | null;
  const focusables = () => [...container.querySelectorAll<HTMLElement>('a[href], button, input, select, textarea, [tabindex]:not([tabindex="-1"])')]
    .filter((el) => !el.hasAttribute('disabled'));
  const onKey = (e: KeyboardEvent) => {
    if (e.key !== 'Tab') return;
    const list = focusables();
    if (!list.length) return;
    const first = list[0], last = list[list.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  };
  document.addEventListener('keydown', onKey);
  focusables()[0]?.focus();
  return () => { document.removeEventListener('keydown', onKey); prev?.focus(); };
}

export function parseToolCall(text: string): ToolCall | null {
  const json = text.match(/\{\s*"name"\s*:\s*"([^"]+)"[\s\S]*?"arguments"\s*:\s*(\{[\s\S]*?\})\s*\}/);
  if (json) {
    try { return { name: json[1], args: JSON.parse(json[2]) }; } catch { /* fall through */ }
  }
  const call = text.match(/([a-zA-Z_][a-zA-Z0-9_]*)\s*\(\s*(\{[\s\S]*?\})\s*\)/);
  if (call) {
    try { return { name: call[1], args: JSON.parse(call[2]) }; } catch { /* fall through */ }
  }
  return null;
}

export function renderTree(entries: TreeEntry[], style: 'plain' | 'box' = 'box') {
  const lines: string[] = [];
  const walk = (items: TreeEntry[], prefix: string) => {
    items.forEach((entry, i) => {
      const last = i === items.length - 1;
      const connector = style === 'box' ? (last ? '└── ' : '├── ') : '  ';
      lines.push(prefix + connector + entry.name);
      if (entry.children?.length) walk(entry.children, prefix + (style === 'box' ? (last ? '    ' : '│   ') : '  '));
    });
  };
  walk(entries, '');
  return lines.join('\n');
}

