export async function atomicWriteFile(filePath: string, data: string | Uint8Array): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  const tmp = `${filePath}.${process.pid}.${Date.now()}.tmp`;
  const fh = await fs.open(tmp, 'w');
  try {
    await fh.writeFile(data);
    await fh.sync();            // flush to disk before rename
  } finally {
    await fh.close();
  }
  await fs.rename(tmp, filePath);
}

export function kruskal(n: number, edges: Array<[number, number, number]>) {
  const sorted = edges.slice().sort((a, b) => a[2] - b[2]);
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x: number): number => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  const mst: Array<[number, number, number]> = [];
  for (const [u, v, w] of sorted) {
    const ru = find(u), rv = find(v);
    if (ru !== rv) { parent[ru] = rv; mst.push([u, v, w]); }
  }
  return mst;
}

