export interface TfidfResult { terms: string[]; vectors: number[][] }
export function tfidf(docs: string[]): TfidfResult

function tokens(text: string) {
  return text.toLowerCase().match(/[a-z0-9]+/g) ?? [];
}
export function tfidf(docs: string[]) {
  const docTokens = docs.map(tokens);
  const df = new Map<string, number>();
  for (const dt of docTokens) for (const t of new Set(dt)) df.set(t, (df.get(t) ?? 0) + 1);
  const terms = [...df.keys()].sort();
  const n = docs.length;
  const vectors = docTokens.map((dt) => {
    const tf = new Map<string, number>();
    for (const t of dt) tf.set(t, (tf.get(t) ?? 0) + 1);
    const len = dt.length || 1;
    return terms.map((term) => {
      const f = tf.get(term) ?? 0;
      const tfs = f === 0 ? 0 : 1 + Math.log(f / len);
      return tfs * Math.log(n / (df.get(term) ?? 1));
    });
  });
  return { terms, vectors };
}

export function badgesEarned(stats: Record<string, number>, milestones: Record<string, number>): { earned: string[]; locked: string[] }

export function badgesEarned(stats: Record<string, number>, milestones: Record<string, number>) {
  const earned: string[] = [], locked: string[] = [];
  for (const [badge, need] of Object.entries(milestones)) (stats[badge] ?? 0) >= need ? earned.push(badge) : locked.push(badge);
  return { earned, locked };
}

export function createTokenBucket(options: { refillPerSec: number; capacity: number }) {
  let tokens = options.capacity;
  let last = Date.now();

  return {
    refill(now = Date.now()) {
      const elapsed = (now - last) / 1000;
      tokens = Math.min(options.capacity, tokens + elapsed * options.refillPerSec);
      last = now;
    },
    take(count = 1) {
      this.refill();
      if (tokens < count) return false;
      tokens -= count;
      return true;
    },
    get available() { return tokens; },
  };
}

