export function wildcardMatch(pattern: string, text: string) {
  let p = 0, s = 0, star = -1, mark = 0;
  while (s < text.length) {
    if (p < pattern.length && (pattern[p] === '?' || pattern[p] === text[s])) { p++; s++; }
    else if (p < pattern.length && pattern[p] === '*') { star = p++; mark = s; }
    else if (star !== -1) { p = star + 1; s = ++mark; }
    else return false;
  }
  while (p < pattern.length && pattern[p] === '*') p++;
  return p === pattern.length;
}

export function hexDump(bytes: Uint8Array, bytesPerLine = 16): string

export function hexDump(bytes: Uint8Array, bytesPerLine = 16) {
  const lines: string[] = [];
  for (let off = 0; off < bytes.length; off += bytesPerLine) {
    const chunk = bytes.slice(off, off + bytesPerLine);
    const hex = [...chunk].map((b) => b.toString(16).padStart(2, '0')).join(' ');
    const ascii = [...chunk].map((b) => (b >= 32 && b < 127 ? String.fromCharCode(b) : '.')).join('');
    lines.push(`${off.toString(16).padStart(8, '0')}  ${hex.padEnd(bytesPerLine * 3 - 1)}  ${ascii}`);
  }
  return lines.join('\n');
}

export async function withTransaction<T>(
  begin: () => Promise<TxExecutor>,
  commit: () => Promise<void>,
  rollback: () => Promise<void>,
  fn: (tx: TxExecutor) => Promise<T>,
): Promise<T> {
  const tx = await begin();
  try {
    const result = await fn(tx);
    await commit();
    return result;
  } catch (e) {
    try { await rollback(); } catch { /* best effort */ }
    throw e;
  }
}

