export interface BfsResult { order: string[]; distances: Map<string, number> }
export function bfs(
  start: string,
  neighbors: (node: string) => string[],
): BfsResult

export function bfs(start: string, neighbors: (node: string) => string[]): BfsResult {
  const queue: string[] = [start];
  const order: string[] = [];
  const distances = new Map<string, number>();
  distances.set(start, 0);

  while (queue.length > 0) {
    const node = queue.shift()!;
    order.push(node);
    for (const next of neighbors(node)) {
      if (distances.has(next)) continue;
      distances.set(next, distances.get(node)! + 1);
      queue.push(next);
    }
  }
  return { order, distances };
}

export function featureHash(terms: string[], buckets: number): number[]

function hashStr(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
export function featureHash(terms: string[], buckets: number) {
  const vec = new Array(buckets).fill(0);
  for (const t of terms) {
    const idx = hashStr(t) % buckets;
    vec[idx] += (hashStr(t + ':sign') & 1) === 0 ? 1 : -1; // signed hashing reduces collisions
  }
  return vec;
}

