export class Histogram {
  constructor(buckets?: number[])
  observe(value: number): void
  get counts(): Record<string, number>
  get cumulative(): Record<string, number>
}

const DEFAULT_BUCKETS = [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10];
export class Histogram {
  private counts = new Map<number, number>();
  private overflow = 0;
  constructor(private buckets = DEFAULT_BUCKETS) {}
  observe(value: number) {
    let placed = false;
    for (const b of this.buckets) {
      if (value <= b) { this.counts.set(b, (this.counts.get(b) ?? 0) + 1); placed = true; break; }
    }
    if (!placed) this.overflow++;
  }
  get counts() {
    const out: Record<string, number> = {};
    for (const [b, c] of this.counts) out[`le_${b}`] = c;
    if (this.overflow) out.overflow = this.overflow;
    return out;
  }
  get cumulative() {
    const out: Record<string, number> = {};
    let running = 0;
    for (const b of this.buckets) { running += this.counts.get(b) ?? 0; out[`le_${b}`] = running; }
    out.overflow = this.overflow;
    return out;
  }
}

export interface Rgb { r: number; g: number; b: number; a?: number }
export interface Hsl { h: number; s: number; l: number }
export function hexToRgb(hex: string): Rgb | null
export function rgbToHex(rgb: Rgb): string
export function rgbToHsl(rgb: Rgb): Hsl
export function hslToRgb(hsl: Hsl): Rgb

export function hexToRgb(hex: string): Rgb | null {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex);
  if (!m) return null;
  const n = parseInt(m[1], 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}
export function rgbToHex(rgb: Rgb) {
  const c = (v: number) => Math.round(Math.min(255, Math.max(0, v))).toString(16).padStart(2, '0');
  return `#${c(rgb.r)}${c(rgb.g)}${c(rgb.b)}`;
}
export function rgbToHsl(rgb: Rgb): Hsl {
  const r = rgb.r / 255, g = rgb.g / 255, b = rgb.b / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  const l = (max + min) / 2;
  if (max === min) return { h: 0, s: 0, l: l * 100 };
  const d = max - min;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  let h = 0;
  if (max === r) h = (g - b) / d + (g < b ? 6 : 0);
  else if (max === g) h = (b - r) / d + 2;
  else h = (r - g) / d + 4;
  return { h: h * 60, s: s * 100, l: l * 100 };
}
export function hslToRgb(hsl: Hsl): Rgb {
  const h = hsl.h / 360, s = hsl.s / 100, l = hsl.l / 100;
  if (s === 0) { const v = l * 255; return { r: v, g: v, b: v }; }
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;
  const hue = (t: number) => {
    let tt = t; if (tt < 0) tt += 1; if (tt > 1) tt -= 1;
    if (tt < 1 / 6) return p + (q - p) * 6 * tt;
    if (tt < 1 / 2) return q;
    if (tt < 2 / 3) return p + (q - p) * (2 / 3 - tt) * 6;
    return p;
  };
  return { r: hue(h + 1 / 3) * 255, g: hue(h) * 255, b: hue(h - 1 / 3) * 255 };
}

export function countingSort(nums: number[], maxValue: number): number[]

export function countingSort(nums: number[], maxValue: number) {
  const count = new Array(maxValue + 1).fill(0);
  for (const x of nums) count[x]++;
  for (let i = 1; i <= maxValue; i++) count[i] += count[i - 1];
  const out = new Array(nums.length);
  for (let i = nums.length - 1; i >= 0; i--) out[--count[nums[i]]] = nums[i];
  return out;
}

export interface BitField { offset: number; width: number }
export function fieldGet(value: number, field: BitField): number
export function fieldSet(value: number, field: BitField, raw: number): number

export function fieldGet(value: number, field: BitField) {
  const mask = (1 << field.width) - 1;
  return (value >>> field.offset) & mask;
}
export function fieldSet(value: number, field: BitField, raw: number) {
  const mask = (1 << field.width) - 1;
  return (value & ~(mask << field.offset)) | ((raw & mask) << field.offset);
}

