export function cliArgs(argv: string[], aliases: Record<string, string> = {}) {
  const flags: Record<string, string | boolean> = {};
  const positionals: string[] = [];
  for (const a of argv) {
    if (a === '--') { positionals.push(...argv.slice(argv.indexOf(a) + 1)); break; }
    if (a.startsWith('--')) {
      const eq = a.indexOf('=');
      const name = eq >= 0 ? a.slice(2, eq) : a.slice(2);
      flags[aliases[name] ?? name] = eq >= 0 ? a.slice(eq + 1) : true;
    } else if (a.startsWith('-') && a.length === 2) {
      const name = aliases[a[1]] ?? a[1];
      flags[name] = true;
    } else positionals.push(a);
  }
  return { flags, positionals };
}

export function getCookie(name: string): string | null
export function setCookie(name: string, value: string, opts?: { maxAgeSec?: number; path?: string; secure?: boolean; sameSite?: 'Lax' | 'Strict' | 'None' }): void
export function deleteCookie(name: string, path?: string): void

export function getCookie(name: string) {
