}

export class Strategy<K extends string, R, A extends unknown[]> {
  set(key: K, fn: (...args: A) => R): void
  run(key: K, ...args: A): R
}

export class Strategy<K extends string, R, A extends unknown[]> {
  private map = new Map<K, (...args: A) => R>();
  set(key: K, fn: (...args: A) => R) { this.map.set(key, fn); }
  run(key: K, ...args: A) {
    const fn = this.map.get(key);
    if (!fn) throw new Error(`No strategy for: ${key}`);
    return fn(...args);
  }
}

export function compactWhitespace(s: string) {
  return s.replace(/\s+/g, ' ').trim();
}

export function dedupeBySimilarity(items: string[], threshold = 0.85): string[]

function jaccard(a: Set<string>, b: Set<string>) {
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter || 1);
}
function shingles(text: string) {
  const t = text.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').trim();
  const words = t.split(/\s+/).filter(Boolean);
  const out = new Set<string>();
  for (let i = 0; i + 2 <= words.length; i++) out.add(words[i] + ' ' + words[i + 1]);
  return out;
}
export function dedupeBySimilarity(items: string[], threshold = 0.85) {
  const kept: string[] = [];
  for (const item of items) {
    const s = shingles(item);
    const dup = kept.some((k) => jaccard(s, shingles(k)) >= threshold);
    if (!dup) kept.push(item);
  }
  return kept;
}

