export async function eventually(fn: () => void | Promise<void>, opts: { timeoutMs?: number; intervalMs?: number } = {}) {
  const { timeoutMs = 2000, intervalMs = 20 } = opts;
  const deadline = Date.now() + timeoutMs;
  let lastErr: unknown;
  while (Date.now() < deadline) {
    try { await fn(); return; } catch (e) { lastErr = e; }
    await new Promise((r) => setTimeout(r, intervalMs));
  }
  throw lastErr;
}

export interface SemVer { major: number; minor: number; patch: number }
export function parseSemVer(v: string): SemVer | null
export function compareSemVer(a: SemVer, b: SemVer): number
export function bumpSemVer(v: string, part: 'major' | 'minor' | 'patch'): string

export function parseSemVer(v: string): SemVer | null {
  const m = /^(\d+)\.(\d+)\.(\d+)(?:[-+].*)?$/.exec(v.trim());
  return m ? { major: +m[1], minor: +m[2], patch: +m[3] } : null;
}
export function compareSemVer(a: SemVer, b: SemVer) {
  for (const k of ['major', 'minor', 'patch'] as const) {
    if (a[k] !== b[k]) return a[k] > b[k] ? 1 : -1;
  }
  return 0;
}
export function bumpSemVer(v: string, part: 'major' | 'minor' | 'patch') {
  const s = parseSemVer(v);
  if (!s) return v;
  if (part === 'major') { s.major++; s.minor = 0; s.patch = 0; }
  else if (part === 'minor') { s.minor++; s.patch = 0; }
  else s.patch++;
  return `${s.major}.${s.minor}.${s.patch}`;
}

export function fixedFormat(scaled: number, decimals: number): string
export function fixedParse(text: string, decimals: number): number

export function fixedFormat(scaled: number, decimals: number) {
  const neg = scaled < 0;
  const v = Math.abs(scaled);
  const f = Math.pow(10, decimals);
  const int = Math.floor(v / f);
  const frac = String(v % f).padStart(decimals, '0');
  return (neg ? '-' : '') + int + '.' + frac;
}
export function fixedParse(text: string, decimals: number) {
  const neg = text.startsWith('-');
  const clean = text.replace('-', '').replace('.', '');
  const f = Math.pow(10, decimals);
  const v = parseInt(clean || '0', 10);
  const scaled = decimals > 0 ? Math.round(v / (f / 1000)) * (f / 1000) : v;
  return (neg ? -1 : 1) * Math.round(scaled);
}

