export function annuityFutureValue(deposit: number, ratePerPeriod: number, periods: number) {
  if (ratePerPeriod === 0) return deposit * periods;
  const g = Math.pow(1 + ratePerPeriod, periods);
  return deposit * ((g - 1) / ratePerPeriod);
}

function npvAt(cashFlows: number[], r: number) {
  return cashFlows.reduce((s, cf, t) => s + cf / Math.pow(1 + r, t), 0);
}
export function irr(cashFlows: number[], guess = 0.1, maxIter = 100) {
  let lo = -0.9999, hi = 10, r = guess;
  for (let i = 0; i < maxIter; i++) {
    const f = npvAt(cashFlows, r);
    if (Math.abs(f) < 1e-8) break;
    if (f > 0) { lo = r; r = (r + hi) / 2; }
    else { hi = r; r = (lo + r) / 2; }
  }
  return r;
}

export function createEventEmitter<T extends EventMap>() {
  const listeners = new Map<keyof T, Set<(...args: never[]) => void>>();

  return {
    on(event, fn) {
      if (!listeners.has(event)) listeners.set(event, new Set());
      listeners.get(event)!.add(fn as (...args: never[]) => void);
      return () => listeners.get(event)?.delete(fn as (...args: never[]) => void);
    },
    off(event, fn) {
      listeners.get(event)?.delete(fn as (...args: never[]) => void);
    },
    emit(event, ...args) {
      listeners.get(event)?.forEach((fn) => (fn as (...a: unknown[]) => void)(...args));
    },
  };
}

export class MinMaxHeap {
  push(v: number): void
  peekMin(): number | undefined
  peekMax(): number | undefined
  popMin(): number | undefined
  popMax(): number | undefined
  get size(): number
}

export class MinMaxHeap {
  private a: number[] = [];
  get size() { return this.a.length; }
  push(v: number) {
    this.a.push(v);
    let i = this.a.length - 1;
    const isMinLevel = (idx: number) => Math.floor(Math.log2(idx + 1)) % 2 === 0;
    const parent = (j: number) => (j - 1) >> 1;
    const grand = (j: number) => parent(parent(j));
    while (i > 0) {
      const p = parent(i);
      if (isMinLevel(i)) {
        if (this.a[i] < this.a[p]) { [this.a[i], this.a[p]] = [this.a[p], this.a[i]]; i = p; }
        else if (i > 2 && this.a[i] > this.a[grand(i)]) { const g = grand(i); [this.a[i], this.a[g]] = [this.a[g], this.a[i]]; i = g; }
        else break;
      } else {
        if (this.a[i] > this.a[p]) { [this.a[i], this.a[p]] = [this.a[p], this.a[i]]; i = p; }
        else if (i > 2 && this.a[i] < this.a[grand(i)]) { const g = grand(i); [this.a[i], this.a[g]] = [this.a[g], this.a[i]]; i = g; }
        else break;
      }
    }
  }
  peekMin() { return this.a[0]; }
  peekMax() { return this.a.length < 2 ? this.a[0] : this.a.length < 3 ? this.a[1] : Math.max(this.a[1], this.a[2]); }
  popMin() {
    if (!this.a.length) return undefined;
    const min = this.a[0];
    this.a[0] = this.a.pop()!;
    return min;
  }
  popMax() {
    if (!this.a.length) return undefined;
    if (this.a.length < 2) return this.a.pop();
    if (this.a.length < 3) return this.a.pop();
    const mi = this.a[1] >= this.a[2] ? 1 : 2;
    const max = this.a[mi];
    this.a[mi] = this.a.pop()!;
    return max;
  }
}

export function alphaBeta<S, M>(game: MinimaxGame<S, M>, state: S, depth: number, alpha: number, beta: number, isMax: boolean): number
export function bestMoveAB<S, M>(game: MinimaxGame<S, M>, state: S, depth?: number): M | null

export function alphaBeta<S, M>(
  game: MinimaxGame<S, M>, state: S, depth: number, alpha: number, beta: number, isMax: boolean,
): number {
  if (depth === 0 || game.isTerminal(state)) return game.evaluate(state);
  const moves = game.getMoves(state);
  if (moves.length === 0) return game.evaluate(state);

  if (isMax) {
    let value = -Infinity;
    for (const m of moves) {
      value = Math.max(value, alphaBeta(game, game.apply(state, m), depth - 1, alpha, beta, false));
      alpha = Math.max(alpha, value);
      if (alpha >= beta) break;   // prune
    }
    return value;
  }
  let value = Infinity;
  for (const m of moves) {
    value = Math.min(value, alphaBeta(game, game.apply(state, m), depth - 1, alpha, beta, true));
    beta = Math.min(beta, value);
    if (alpha >= beta) break;     // prune
  }
  return value;
}

export function bestMoveAB<S, M>(game: MinimaxGame<S, M>, state: S, depth = 6): M | null {
  let best: M | null = null;
  let bestScore = -Infinity;
  let alpha = -Infinity;
  const beta = Infinity;
  for (const m of game.getMoves(state)) {
    const score = alphaBeta(game, game.apply(state, m), depth - 1, alpha, beta, false);
    if (score > bestScore) { bestScore = score; best = m; }
    alpha = Math.max(alpha, score);
  }
  return best;
}

export function modExp(base: number, exp: number, mod: number): number

export function modExp(base: number, exp: number, mod: number) {
  if (mod === 0) return NaN;
  let result = 1n, b = BigInt(base) % BigInt(mod), e = BigInt(exp), m = BigInt(mod);
  while (e > 0n) { if (e & 1n) result = (result * b) % m; b = (b * b) % m; e >>= 1n; }
  return Number(result);
}

