export interface AmortRow { period: number; payment: number; principal: number; interest: number; balance: number }
export function amortization(principal: number, annualRate: number, years: number, paymentsPerYear = 12): AmortRow[]

export function amortization(principal: number, annualRate: number, years: number, paymentsPerYear = 12) {
  const n = years * paymentsPerYear;
  const r = annualRate / paymentsPerYear;
  const payment = r === 0 ? principal / n : (principal * r) / (1 - Math.pow(1 + r, -n));
  const rows: AmortRow[] = [];
  let balance = principal;
  for (let period = 1; period <= n; period++) {
    const interest = balance * r;
    const principalPart = payment - interest;
    balance -= principalPart;
    rows.push({ period, payment, principal: principalPart, interest, balance: Math.max(0, balance) });
  }
  return rows;
}

const IRREGULAR: Record<string, string> = {
  person: 'people', child: 'children', mouse: 'mice', foot: 'feet',
  tooth: 'teeth', goose: 'geese', ox: 'oxen', man: 'men', woman: 'women',
};
export function pluralize(word: string, count?: number) {
  if (count === 1) return word;
  if (IRREGULAR[word.toLowerCase()]) return IRREGULAR[word.toLowerCase()];
  if (/(s|x|z|ch|sh)$/i.test(word)) return word + 'es';
  if (/[^aeiou]y$/i.test(word)) return word.slice(0, -1) + 'ies';
  if (/fe?$/i.test(word) && !/^[a-z]+fe$/i.test(word)) return word.replace(/fe?$/, 'ves');
  return word + 's';
}

export function diffPaths(before: Record<string, unknown>, after: Record<string, unknown>): DeltaPatch {
  const patch: DeltaPatch = [];
  const walk = (a: Record<string, unknown>, b: Record<string, unknown>, base: string) => {
    const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
    for (const k of keys) {
      const path = base ? `${base}.${k}` : k;
      const av = a[k], bv = b[k];
      if (JSON.stringify(av) === JSON.stringify(bv)) continue;
      if (av && bv && typeof av === 'object' && typeof bv === 'object' && !Array.isArray(av) && !Array.isArray(bv)) {
        walk(av as Record<string, unknown>, bv as Record<string, unknown>, path);
      } else {
        patch.push({ path, value: bv });
      }
    }
  };
  walk(before, after, '');
  return patch;
}
export function applyPatch(target: Record<string, unknown>, patch: DeltaPatch) {
  const out: Record<string, unknown> = JSON.parse(JSON.stringify(target));
  for (const { path, value } of patch) {
    const parts = path.split('.');
    let node = out;
    for (let i = 0; i < parts.length - 1; i++) node = node[parts[i]] as Record<string, unknown>;
    node[parts[parts.length - 1]] = value;
  }
  return out;
}

