export function niceTicks(min: number, max: number, count = 5) {
  if (min === max) return [min];
  const span = max - min;
  const rawStep = span / Math.max(1, count);
  const mag = Math.pow(10, Math.floor(Math.log10(rawStep)));
  const norm = rawStep / mag;
  const step = (norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10) * mag;
  const ticks: number[] = [];
  for (let v = Math.ceil(min / step) * step; v <= max + step * 1e-9; v += step) ticks.push(Math.round(v * 1e9) / 1e9);
  return ticks;
}

export function knn(train: KnnSample[], query: number[], k = 3) {
  const dist = (a: number[], b: number[]) => {
    let s = 0;
    for (let i = 0; i < a.length; i++) s += (a[i] - b[i]) ** 2;
    return Math.sqrt(s);
  };
  const nearest = train
    .map((s) => ({ label: s.label, d: dist(s.x, query) }))
    .sort((a, b) => a.d - b.d)
    .slice(0, k);
  const tally = new Map<string, number>();
  for (const n of nearest) tally.set(n.label, (tally.get(n.label) ?? 0) + 1);
  let best = nearest[0].label, bestN = -1;
  for (const [label, n] of tally) if (n > bestN) { bestN = n; best = label; }
  return best;
}

export function bezierQuad(p0: Vec2, p1: Vec2, p2: Vec2, t: number): Vec2
export function bezierCubic(p0: Vec2, p1: Vec2, p2: Vec2, p3: Vec2, t: number): Vec2
export function bezierPoints(pts: Vec2[], steps?: number): Vec2[]

export function bezierQuad(p0: Vec2, p1: Vec2, p2: Vec2, t: number): Vec2 {
  const mt = 1 - t;
  return {
    x: mt * mt * p0.x + 2 * mt * t * p1.x + t * t * p2.x,
    y: mt * mt * p0.y + 2 * mt * t * p1.y + t * t * p2.y,
  };
}
export function bezierCubic(p0: Vec2, p1: Vec2, p2: Vec2, p3: Vec2, t: number): Vec2 {
  const mt = 1 - t;
  return {
    x: mt ** 3 * p0.x + 3 * mt * mt * t * p1.x + 3 * mt * t * t * p2.x + t ** 3 * p3.x,
    y: mt ** 3 * p0.y + 3 * mt * mt * t * p1.y + 3 * mt * t * t * p2.y + t ** 3 * p3.y,
  };
}
export function bezierPoints(pts: Vec2[], steps = 20) {
  const out: Vec2[] = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    out.push(pts.length === 3 ? bezierQuad(pts[0], pts[1], pts[2], t) : bezierCubic(pts[0], pts[1], pts[2], pts[3], t));
  }
  return out;
}

export class RollingStats {
