export class FrequencyCounter<T> {
  private map = new Map<T, number>();
  add(item: T) {
    const c = (this.map.get(item) ?? 0) + 1;
    this.map.set(item, c);
    return c;
  }
  count(item: T) { return this.map.get(item) ?? 0; }
  top(n: number) {
    return [...this.map.entries()].sort((a, b) => b[1] - a[1]).slice(0, n);
  }
}

export function addBusinessDays(date: Date, days: number, holidays: Set<string> = new Set()) {
  const out = new Date(date);
  const key = (d: Date) => d.toISOString().slice(0, 10);
  let remaining = days;
  while (remaining > 0) {
    out.setDate(out.getDate() + 1);
    const dow = out.getDay();
    if (dow === 0 || dow === 6 || holidays.has(key(out))) continue;
    remaining--;
  }
  return out;
}

function cmp(a: string, b: string) {
  const pa = a.split('.').map(Number), pb = b.split('.').map(Number);
  for (let i = 0; i < 3; i++) { if ((pa[i] ?? 0) !== (pb[i] ?? 0)) return (pa[i] ?? 0) > (pb[i] ?? 0) ? 1 : -1; }
  return 0;
}
export function isStale(current: string, latest: string) { return cmp(current, latest) < 0; }
export async function checkForUpdate(opts: { current: string; fetchLatest: () => Promise<string> }) {
  try { return isStale(opts.current, await opts.fetchLatest()) ? 'update-available' : 'up-to-date'; } catch { return 'error'; }
}

