import * as crypto from 'crypto';

export function generateRsaKeyPair(bits = 2048): KeyPair {
  const { publicKey, privateKey } = crypto.generateKeyPairSync('rsa', {
    modulusLength: bits,
    publicKeyEncoding: { type: 'spki', format: 'pem' },
    privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
  });
  return { publicKey, privateKey };
}

export interface ScoreEntry { name: string; score: number; date: string }
export function createHighScoreTable(limit?: number) {
  return {
    add(name: string, score: number): number,   // returns rank (1-based)
    get top(): ScoreEntry[],
    qualifies(score: number): boolean,
    load(entries: ScoreEntry[]): void,
    export(): ScoreEntry[],
  };
}

export function createHighScoreTable(limit = 10) {
  let entries: ScoreEntry[] = [];

  return {
    add(name, score) {
      const entry: ScoreEntry = { name: name.slice(0, 16), score, date: new Date().toISOString() };
      entries.push(entry);
      entries.sort((a, b) => b.score - a.score);
      entries = entries.slice(0, limit);
      return entries.indexOf(entry) + 1;
    },
    get top() { return [...entries]; },
    qualifies(score) {
      return entries.length < limit || score > entries[entries.length - 1].score;
    },
    load(loaded) { entries = [...loaded].sort((a, b) => b.score - a.score).slice(0, limit); },
    export() { return [...entries]; },
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';

export function usePolling<T>(fetcher: () => Promise<T>, intervalMs: number,
  options?: { enabled?: boolean; onError?: (e: Error) => void },
) {
  const [state, setState] = useState<PollingState<T>>({ data: null, error: null, loading: false });
  const timer = useRef<ReturnType<typeof setInterval> | undefined>(undefined);
  const fetcherRef = useRef(fetcher);
  fetcherRef.current = fetcher;

  const tick = useCallback(async () => {
    try {
      setState((s) => ({ ...s, loading: true }));
      const data = await fetcherRef.current();
      setState({ data, error: null, loading: false });
    } catch (e) {
      setState((s) => ({ ...s, error: e as Error, loading: false }));
      options?.onError?.(e as Error);
    }
  }, [options]);

  const start = useCallback(() => {
    if (timer.current) return;
    void tick();
    timer.current = setInterval(() => void tick(), intervalMs);
  }, [tick, intervalMs]);

  const stop = useCallback(() => {
    if (timer.current) clearInterval(timer.current);
    timer.current = undefined;
  }, []);

  useEffect(() => {
    if (options?.enabled !== false) start();
    return stop;
  }, [start, stop, options?.enabled]);

  return { ...state, refresh: tick, stop, start };
}

const DANGEROUS = /[;&|`$()<>*?\[\]{}\n\r\\]/;
export function hasShellDanger(input: string) {
  return DANGEROUS.test(input);
}
export function assertSafeShell(input: string, allow?: RegExp) {
  const cleaned = allow ? input.replace(allow, '') : input;
  return hasShellDanger(cleaned)
    ? { ok: false, error: 'Unsafe shell characters detected' }
    : { ok: true };
}

export function heatmapColor(v: number, min: number, max: number) {
  const t = max === min ? 0.5 : (v - min) / (max - min);
  const r = Math.round(255 * Math.min(1, Math.max(0, (t - 0.5) * 2)));
  const b = Math.round(255 * Math.min(1, Math.max(0, (0.5 - t) * 2)));
  const g = Math.round(255 * (1 - Math.abs(t - 0.5) * 2));
  return `rgb(${r},${g},${b})`;
}

